// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.30;

import "./IEntryPoint.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title BaseAccount
 * @dev ERC-4337 账户基础合约
 * @notice 基于官方 account-abstraction 实现
 */
abstract contract BaseAccount {
    using ECDSA for bytes32;
    
    // ============ Custom Errors ============
    
    error NotFromEntryPoint();
    error NotFromEntryPointOrOwner();
    
    // ============ 修饰符 ============
    
    /**
     * @dev 确保调用者是 EntryPoint
     */
    modifier onlyEntryPoint() {
        if (msg.sender != address(entryPoint())) revert NotFromEntryPoint();
        _;
    }
    
    /**
     * @dev 确保调用者是 EntryPoint 或 Owner
     */
    modifier onlyEntryPointOrOwner() {
        if (msg.sender != address(entryPoint()) && msg.sender != owner()) {
            revert NotFromEntryPointOrOwner();
        }
        _;
    }
    
    // ============ 抽象函数 ============
    
    /**
     * @dev 返回 EntryPoint 地址
     */
    function entryPoint() public view virtual returns (IEntryPoint);
    
    /**
     * @dev 返回账户所有者
     */
    function owner() public view virtual returns (address);
    
    /**
     * @dev 验证用户操作签名
     * @param userOp 用户操作
     * @param userOpHash 用户操作哈希
     * @return validationData 验证数据（0 表示成功）
     */
    function _validateSignature(
        IEntryPoint.UserOperation calldata userOp,
        bytes32 userOpHash
    ) internal virtual returns (uint256 validationData);
    
    // ============ EntryPoint 调用函数 ============
    
    /**
     * @dev 验证用户操作
     * @param userOp 用户操作
     * @param userOpHash 用户操作哈希
     * @param missingAccountFunds 缺少的账户资金
     * @return validationData 验证数据
     */
    function validateUserOp(
        IEntryPoint.UserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 missingAccountFunds
    ) external virtual onlyEntryPoint returns (uint256 validationData) {
        validationData = _validateSignature(userOp, userOpHash);
        _payPrefund(missingAccountFunds);
    }
    
    /**
     * @dev 支付预付款
     * @param missingAccountFunds 缺少的资金
     */
    function _payPrefund(uint256 missingAccountFunds) internal {
        if (missingAccountFunds != 0) {
            (bool success,) = payable(msg.sender).call{
                value: missingAccountFunds,
                gas: type(uint256).max
            }("");
            (success);
        }
    }
    
    /**
     * @dev 执行调用
     * @param dest 目标地址
     * @param value 发送的 ETH 数量
     * @param func 调用数据
     */
    function execute(
        address dest,
        uint256 value,
        bytes calldata func
    ) external onlyEntryPointOrOwner {
        _call(dest, value, func);
    }
    
    /**
     * @dev 批量执行调用
     * @param dest 目标地址数组
     * @param value ETH 数量数组
     * @param func 调用数据数组
     */
    function executeBatch(
        address[] calldata dest,
        uint256[] calldata value,
        bytes[] calldata func
    ) external onlyEntryPointOrOwner {
        require(dest.length == func.length && dest.length == value.length, "Length mismatch");
        for (uint256 i = 0; i < dest.length;) {
            _call(dest[i], value[i], func[i]);
            unchecked {
                ++i;  // Gas 优化
            }
        }
    }
    
    /**
     * @dev 内部调用函数
     */
    function _call(address target, uint256 value, bytes memory data) internal {
        (bool success, bytes memory result) = target.call{value: value}(data);
        if (!success) {
            assembly {
                revert(add(result, 32), mload(result))
            }
        }
    }
    
    /**
     * @dev 获取存款
     */
    function getDeposit() public view returns (uint256) {
        return entryPoint().balanceOf(address(this));
    }
    
    /**
     * @dev 添加存款
     */
    function addDeposit() public payable {
        entryPoint().depositTo{value: msg.value}(address(this));
    }
    
    /**
     * @dev 提取存款
     * @param withdrawAddress 提取地址
     * @param amount 提取数量
     */
    function withdrawDepositTo(
        address payable withdrawAddress,
        uint256 amount
    ) public onlyEntryPointOrOwner {
        entryPoint().withdrawTo(withdrawAddress, amount);
    }
    
    /**
     * @dev 接收 ETH
     */
    receive() external payable {}
}

contracts/aa/DIAPAccount.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "./BaseAccount.sol";
import "./IEntryPoint.sol";
import "./IERC1271.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title DIAPAccount
 * @dev DIAP 智能体 ERC-4337 账户合约
 * @notice 支持 Session Key、支出限额、白名单等功能
 */
contract DIAPAccount is BaseAccount, Initializable, IERC1271 {
    using ECDSA for bytes32;
    
    // ============ Custom Errors ============
    
    error OnlyOwner();
    error InvalidSessionKey();
    error SessionKeyExpired();
    error DailyLimitExceeded();
    error PerTxLimitExceeded();
    error NotWhitelisted();
    error AccountFrozen();
    error InvalidSignature();
    error ZeroAddress();
    error InvalidLimit();
    error SessionKeyNotFound();
    
    // ============ 状态变量 ============
    
    IEntryPoint private immutable ENTRY_POINT;
    address private _owner;
    bool private _frozen;
    
    // Session Key 管理
    struct SessionKeyData {
        uint256 validUntil;       // 有效期
        uint256 dailyLimit;       // 每日限额
        uint256 perTxLimit;       // 单笔限额
        uint256 spentToday;       // 今日已花费
        uint256 lastResetTime;    // 上次重置时间
        bool isActive;            // 是否激活
    }
    
    mapping(address => SessionKeyData) public sessionKeys;
    address[] public sessionKeyList;
    
    // Nonce 管理（防止重放攻击）
    mapping(address => uint256) public sessionKeyNonces;
    
    // 支出限额
    uint256 public defaultDailyLimit;
    uint256 public defaultPerTxLimit;
    
    // 批量操作限制
    uint256 public constant MAX_BATCH_SIZE = 50;
    
    // 白名单
    mapping(address => bool) public whitelist;
    address[] public whitelistAddresses;
    
    // ============ 事件定义 ============
    
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event SessionKeyAdded(address indexed key, uint256 validUntil, uint256 dailyLimit);
    event SessionKeyRemoved(address indexed key);
    event SessionKeyUsed(address indexed key, uint256 amount);
    event DailyLimitUpdated(uint256 newLimit);
    event PerTxLimitUpdated(uint256 newLimit);
    event WhitelistAdded(address indexed target);
    event WhitelistRemoved(address indexed target);
    event AccountFrozenEvent();
    event AccountUnfrozenEvent();
    event Executed(address indexed target, uint256 value, bytes data);
    
    // ============ 修饰符 ============
    
    modifier onlyOwner() {
        if (msg.sender != _owner) revert OnlyOwner();
        _;
    }
    
    modifier notFrozen() {
        if (_frozen) revert AccountFrozen();
        _;
    }
    
    // ============ 构造函数 ============
    
    constructor(IEntryPoint anEntryPoint) {
        ENTRY_POINT = anEntryPoint;
        _disableInitializers();
    }
    
    /**
     * @dev 初始化账户
     * @param anOwner 所有者地址
     */
    function initialize(address anOwner) public initializer {
        if (anOwner == address(0)) revert ZeroAddress();
        _owner = anOwner;
        
        // 设置默认限额
        defaultDailyLimit = 1000 * 10**18;  // 1000 DIAP
        defaultPerTxLimit = 100 * 10**18;   // 100 DIAP
        
        emit OwnershipTransferred(address(0), anOwner);
    }
    
    // ============ BaseAccount 实现 ============
    
    function entryPoint() public view override returns (IEntryPoint) {
        return ENTRY_POINT;
    }
    
    function owner() public view override returns (address) {
        return _owner;
    }
    
    /**
     * @dev 验证签名（包含 nonce 检查防止重放攻击）
     */
    function _validateSignature(
        IEntryPoint.UserOperation calldata userOp,
        bytes32 userOpHash
    ) internal override returns (uint256 validationData) {
        bytes32 hash = userOpHash.toEthSignedMessageHash();
        address signer = hash.recover(userOp.signature);
        
        // 检查是否是 owner
        if (signer == _owner) {
            return 0;
        }
        
        // 检查是否是有效的 Session Key
        SessionKeyData storage sessionKey = sessionKeys[signer];
        if (!sessionKey.isActive) {
            return 1; // 签名无效
        }
        
        if (block.timestamp > sessionKey.validUntil) {
            return 1; // Session Key 已过期
        }
        
        // 验证并更新 nonce（防止重放攻击）
        uint256 expectedNonce = sessionKeyNonces[signer];
        if (userOp.nonce != expectedNonce) {
            return 1; // Nonce 不匹配
        }
        unchecked {
            ++sessionKeyNonces[signer];  // Gas 优化
        }
        
        // Session Key 验证成功
        return 0;
    }
    
    // ============ Session Key 管理 ============
    
    /**
     * @dev 添加 Session Key
     * @param key Session Key 地址
     * @param validUntil 有效期
     * @param dailyLimit 每日限额
     * @param perTxLimit 单笔限额
     */
    function addSessionKey(
        address key,
        uint256 validUntil,
        uint256 dailyLimit,
        uint256 perTxLimit
    ) external onlyOwner {
        if (key == address(0)) revert ZeroAddress();
        if (validUntil <= block.timestamp) revert InvalidSessionKey();
        if (dailyLimit == 0 || perTxLimit == 0) revert InvalidLimit();
        
        if (!sessionKeys[key].isActive) {
            sessionKeyList.push(key);
        }
        
        sessionKeys[key] = SessionKeyData({
            validUntil: validUntil,
            dailyLimit: dailyLimit,
            perTxLimit: perTxLimit,
            spentToday: 0,
            lastResetTime: block.timestamp,
            isActive: true
        });
        
        emit SessionKeyAdded(key, validUntil, dailyLimit);
    }
    
    /**
     * @dev 移除 Session Key
     * @param key Session Key 地址
     */
    function removeSessionKey(address key) external onlyOwner {
        if (!sessionKeys[key].isActive) revert SessionKeyNotFound();
        
        sessionKeys[key].isActive = false;
        
        emit SessionKeyRemoved(key);
    }
    
    /**
     * @dev 获取当天开始时间（UTC 0:00）
     */
    function _getDayStart(uint256 timestamp) internal pure returns (uint256) {
        return (timestamp / 1 days) * 1 days;
    }
    
    /**
     * @dev 检查并更新 Session Key 限额
     * @param key Session Key 地址
     * @param amount 花费金额
     */
    function _checkAndUpdateSessionKeyLimit(address key, uint256 amount) internal {
        SessionKeyData storage sessionKey = sessionKeys[key];
        
        if (!sessionKey.isActive) revert InvalidSessionKey();
        if (block.timestamp > sessionKey.validUntil) revert SessionKeyExpired();
        
        // 检查单笔限额
        if (amount > sessionKey.perTxLimit) revert PerTxLimitExceeded();
        
        // 使用固定的 UTC 时间重置每日限额
        uint256 currentDayStart = _getDayStart(block.timestamp);
        uint256 lastDayStart = _getDayStart(sessionKey.lastResetTime);
        
        if (currentDayStart > lastDayStart) {
            sessionKey.spentToday = 0;
            sessionKey.lastResetTime = currentDayStart;
        }
        
        // 检查每日限额
        if (sessionKey.spentToday + amount > sessionKey.dailyLimit) {
            revert DailyLimitExceeded();
        }
        
        // 更新已花费金额
        sessionKey.spentToday += amount;
        
        emit SessionKeyUsed(key, amount);
    }
    
    // ============ 限额管理 ============
    
    /**
     * @dev 设置默认每日限额
     * @param limit 新限额
     */
    function setDefaultDailyLimit(uint256 limit) external onlyOwner {
        if (limit == 0) revert InvalidLimit();
        defaultDailyLimit = limit;
        emit DailyLimitUpdated(limit);
    }
    
    /**
     * @dev 设置默认单笔限额
     * @param limit 新限额
     */
    function setDefaultPerTxLimit(uint256 limit) external onlyOwner {
        if (limit == 0) revert InvalidLimit();
        defaultPerTxLimit = limit;
        emit PerTxLimitUpdated(limit);
    }
    
    // ============ 白名单管理 ============
    
    /**
     * @dev 添加到白名单
     * @param target 目标地址
     */
    function addToWhitelist(address target) external onlyOwner {
        if (target == address(0)) revert ZeroAddress();
        if (!whitelist[target]) {
            whitelist[target] = true;
            whitelistAddresses.push(target);
            emit WhitelistAdded(target);
        }
    }
    
    /**
     * @dev 从白名单移除
     * @param target 目标地址
     */
    function removeFromWhitelist(address target) external onlyOwner {
        if (whitelist[target]) {
            whitelist[target] = false;
            emit WhitelistRemoved(target);
        }
    }
    
    /**
     * @dev 批量添加到白名单
     * @param targets 目标地址数组
     */
    function batchAddToWhitelist(address[] calldata targets) external onlyOwner {
        require(targets.length <= MAX_BATCH_SIZE, "Batch too large");
        
        for (uint256 i = 0; i < targets.length;) {
            if (targets[i] != address(0) && !whitelist[targets[i]]) {
                whitelist[targets[i]] = true;
                whitelistAddresses.push(targets[i]);
                emit WhitelistAdded(targets[i]);
            }
            unchecked { ++i; }  // Gas 优化
        }
    }
    
    // ============ 账户控制 ============
    
    /**
     * @dev 冻结账户
     */
    function freeze() external onlyOwner {
        _frozen = true;
        emit AccountFrozenEvent();
    }
    
    /**
     * @dev 解冻账户
     */
    function unfreeze() external onlyOwner {
        _frozen = false;
        emit AccountUnfrozenEvent();
    }
    
    /**
     * @dev 转移所有权
     * @param newOwner 新所有者
     */
    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }
    
    // ============ 执行函数（带限额检查）============
    
    /**
     * @dev 执行调用（带 Session Key 限额检查）
     * @param dest 目标地址
     * @param value 发送的 ETH 数量
     * @param func 调用数据
     */
    function executeWithSessionKey(
        address dest,
        uint256 value,
        bytes calldata func
    ) external notFrozen {
        // 只有通过 EntryPoint 或 owner 可以调用
        if (msg.sender != address(entryPoint()) && msg.sender != _owner) {
            revert NotFromEntryPointOrOwner();
        }
        
        // 如果不是 owner，检查白名单和限额
        if (msg.sender != _owner) {
            if (!whitelist[dest]) revert NotWhitelisted();
            
            // 注意：这里简化了 Session Key 的获取
            // 生产环境应该从 UserOperation 的签名中解析
            // 暂时跳过限额检查，由 validateUserOp 处理
        }
        
        _call(dest, value, func);
        emit Executed(dest, value, func);
    }
    
    // ============ 代币操作 ============
    
    /**
     * @dev 转移 ERC20 代币
     * @param token 代币地址
     * @param to 接收地址
     * @param amount 数量
     */
    function transferToken(
        address token,
        address to,
        uint256 amount
    ) external onlyEntryPointOrOwner notFrozen {
        IERC20(token).transfer(to, amount);
    }
    
    /**
     * @dev 批量转移 ERC20 代币
     * @param token 代币地址
     * @param recipients 接收地址数组
     * @param amounts 数量数组
     */
    function batchTransferToken(
        address token,
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external onlyEntryPointOrOwner notFrozen {
        require(recipients.length == amounts.length, "Length mismatch");
        require(recipients.length <= MAX_BATCH_SIZE, "Batch too large");
        
        for (uint256 i = 0; i < recipients.length;) {
            IERC20(token).transfer(recipients[i], amounts[i]);
            unchecked { ++i; }  // Gas 优化
        }
    }
    
    // ============ 查询函数 ============
    
    /**
     * @dev 获取 Session Key 信息
     * @param key Session Key 地址
     */
    function getSessionKeyInfo(address key) external view returns (
        uint256 validUntil,
        uint256 dailyLimit,
        uint256 perTxLimit,
        uint256 spentToday,
        uint256 remainingToday,
        bool isActive
    ) {
        SessionKeyData memory sessionKey = sessionKeys[key];
        
        uint256 remaining = 0;
        if (sessionKey.isActive && block.timestamp < sessionKey.validUntil) {
            // 检查是否需要重置
            if (block.timestamp >= sessionKey.lastResetTime + 1 days) {
                remaining = sessionKey.dailyLimit;
            } else {
                remaining = sessionKey.dailyLimit > sessionKey.spentToday 
                    ? sessionKey.dailyLimit - sessionKey.spentToday 
                    : 0;
            }
        }
        
        return (
            sessionKey.validUntil,
            sessionKey.dailyLimit,
            sessionKey.perTxLimit,
            sessionKey.spentToday,
            remaining,
            sessionKey.isActive
        );
    }
    
    /**
     * @dev 获取所有 Session Keys
     */
    function getAllSessionKeys() external view returns (address[] memory) {
        return sessionKeyList;
    }
    
    /**
     * @dev 获取所有白名单地址
     */
    function getWhitelist() external view returns (address[] memory) {
        return whitelistAddresses;
    }
    
    /**
     * @dev 检查地址是否在白名单
     */
    function isWhitelisted(address target) external view returns (bool) {
        return whitelist[target];
    }
    
    /**
     * @dev 检查账户是否冻结
     */
    function isFrozen() external view returns (bool) {
        return _frozen;
    }
    
    /**
     * @dev 获取代币余额
     * @param token 代币地址
     */
    function getTokenBalance(address token) external view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }
    
    // ============ EIP-1271 签名验证 ============
    
    /**
     * @dev EIP-1271 签名验证
     * @param hash 数据哈希
     * @param signature 签名
     * @return magicValue 魔术值
     */
    function isValidSignature(
        bytes32 hash,
        bytes memory signature
    ) external view override returns (bytes4 magicValue) {
        bytes32 messageHash = hash.toEthSignedMessageHash();
        address signer = messageHash.recover(signature);
        
        // 检查是否是 owner
        if (signer == _owner) {
            return 0x1626ba7e; // EIP-1271 魔术值
        }
        
        // 检查是否是有效的 Session Key
        SessionKeyData storage sessionKey = sessionKeys[signer];
        if (sessionKey.isActive && block.timestamp <= sessionKey.validUntil) {
            return 0x1626ba7e;
        }
        
        return 0xffffffff; // 无效签名
    }
}

contracts/aa/DIAPAccountFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "./DIAPAccount.sol";
import "./IEntryPoint.sol";
import "@openzeppelin/contracts/utils/Create2.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";

/**
 * @title DIAPAccountFactory
 * @dev DIAP 智能体账户工厂合约
 * @notice 使用 CREATE2 创建可预测地址的账户
 */
contract DIAPAccountFactory {
    
    // ============ Custom Errors ============
    
    error AccountAlreadyExists();
    error ZeroAddress();
    
    // ============ 状态变量 ============
    
    DIAPAccount public immutable ACCOUNT_IMPLEMENTATION;
    IEntryPoint public immutable ENTRY_POINT;
    
    // 账户注册表
    mapping(address => address) public ownerToAccount;  // owner => account
    mapping(address => address) public accountToOwner;  // account => owner
    address[] public allAccounts;
    
    // ============ 事件定义 ============
    
    event AccountCreated(
        address indexed account,
        address indexed owner,
        uint256 salt
    );
    
    // ============ 构造函数 ============
    
    constructor(IEntryPoint _entryPoint) {
        if (address(_entryPoint) == address(0)) revert ZeroAddress();
        
        ENTRY_POINT = _entryPoint;
        ACCOUNT_IMPLEMENTATION = new DIAPAccount(_entryPoint);
    }
    
    // ============ 账户创建 ============
    
    /**
     * @dev 创建账户
     * @param owner 账户所有者
     * @param salt 盐值（用于生成唯一地址）
     * @return account 创建的账户地址
     */
    function createAccount(
        address owner,
        uint256 salt
    ) public returns (DIAPAccount account) {
        if (owner == address(0)) revert ZeroAddress();
        
        address addr = getAddress(owner, salt);
        uint256 codeSize = addr.code.length;
        
        if (codeSize > 0) {
            return DIAPAccount(payable(addr));
        }
        
        // 使用 CREATE2 部署代理合约
        account = DIAPAccount(payable(
            new ERC1967Proxy{salt: bytes32(salt)}(
                address(ACCOUNT_IMPLEMENTATION),
                abi.encodeCall(DIAPAccount.initialize, (owner))
            )
        ));
        
        // 记录到注册表
        ownerToAccount[owner] = address(account);
        accountToOwner[address(account)] = owner;
        allAccounts.push(address(account));
        
        emit AccountCreated(address(account), owner, salt);
    }
    
    /**
     * @dev 获取账户地址（不创建）
     * @param owner 账户所有者
     * @param salt 盐值
     * @return 账户地址
     */
    function getAddress(
        address owner,
        uint256 salt
    ) public view returns (address) {
        return Create2.computeAddress(
            bytes32(salt),
            keccak256(abi.encodePacked(
                type(ERC1967Proxy).creationCode,
                abi.encode(
                    address(ACCOUNT_IMPLEMENTATION),
                    abi.encodeCall(DIAPAccount.initialize, (owner))
                )
            ))
        );
    }
    
    /**
     * @dev 批量创建账户
     * @param owners 所有者地址数组
     * @param salts 盐值数组
     * @return accounts 创建的账户地址数组
     */
    function batchCreateAccounts(
        address[] calldata owners,
        uint256[] calldata salts
    ) external returns (address[] memory accounts) {
        require(owners.length == salts.length, "Length mismatch");
        require(owners.length <= 50, "Batch too large");
        
        accounts = new address[](owners.length);
        for (uint256 i = 0; i < owners.length;) {
            DIAPAccount account = createAccount(owners[i], salts[i]);
            accounts[i] = address(account);
            unchecked { ++i; }  // Gas 优化
        }
    }
    
    // ============ 查询函数 ============
    
    /**
     * @dev 根据 owner 获取账户地址
     * @param owner 所有者地址
     * @return 账户地址
     */
    function getAccountByOwner(address owner) external view returns (address) {
        return ownerToAccount[owner];
    }
    
    /**
     * @dev 根据账户地址获取 owner
     * @param account 账户地址
     * @return 所有者地址
     */
    function getOwnerByAccount(address account) external view returns (address) {
        return accountToOwner[account];
    }
    
    /**
     * @dev 获取所有账户
     * @return 所有账户地址数组
     */
    function getAllAccounts() external view returns (address[] memory) {
        return allAccounts;
    }
    
    /**
     * @dev 获取账户总数
     * @return 账户总数
     */
    function getAccountCount() external view returns (uint256) {
        return allAccounts.length;
    }
    
    /**
     * @dev 检查账户是否存在
     * @param account 账户地址
     * @return 是否存在
     */
    function isAccount(address account) external view returns (bool) {
        return accountToOwner[account] != address(0);
    }
}

contracts/aa/IEntryPoint.sol.content:
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.30;

/**
 * @title IEntryPoint
 * @dev ERC-4337 EntryPoint 接口
 * @notice 官方 EntryPoint 接口定义
 */
interface IEntryPoint {
    
    struct UserOperation {
        address sender;
        uint256 nonce;
        bytes initCode;
        bytes callData;
        uint256 callGasLimit;
        uint256 verificationGasLimit;
        uint256 preVerificationGas;
        uint256 maxFeePerGas;
        uint256 maxPriorityFeePerGas;
        bytes paymasterAndData;
        bytes signature;
    }
    
    function handleOps(UserOperation[] calldata ops, address payable beneficiary) external;
    
    function handleAggregatedOps(
        UserOperation[] calldata opsPerAggregator,
        address payable beneficiary
    ) external;
    
    function getUserOpHash(UserOperation calldata userOp) external view returns (bytes32);
    
    function depositTo(address account) external payable;
    
    function balanceOf(address account) external view returns (uint256);
    
    function withdrawTo(address payable withdrawAddress, uint256 withdrawAmount) external;
}

contracts/aa/IERC1271.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/**
 * @title IERC1271
 * @dev EIP-1271 标准签名验证接口
 * @notice 用于智能合约账户的签名验证
 */
interface IERC1271 {
    /**
     * @dev 验证签名是否有效
     * @param hash 要验证的数据哈希
     * @param signature 签名数据
     * @return magicValue 如果签名有效返回 0x1626ba7e，否则返回其他值
     */
    function isValidSignature(
        bytes32 hash,
        bytes memory signature
    ) external view returns (bytes4 magicValue);
}

contracts/DIAPAgentNetwork.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title DIAPAgentNetwork
 * @dev 去中心化智能体网络主合约
 * @notice 基于DIAP协议实现智能体身份验证、通信和治理
 */
contract DIAPAgentNetwork is 
    Initializable, 
    UUPSUpgradeable, 
    OwnableUpgradeable, 
    ReentrancyGuardUpgradeable,
    PausableUpgradeable 
{

    // ============ Custom Errors ============

    error InvalidTokenAddress();
    error AgentAlreadyRegistered();
    error InsufficientStakeAmount();
    error StakeAmountTooLarge();
    error InvalidDIDDocument();
    error InvalidIdentifierFormat();
    error MustUseIPNSOrIPFS();
    error DIDAlreadyExists();
    error InsufficientTokenBalance();
    error InsufficientTokenAllowance();
    error TokenTransferFailed();
    error AgentNotRegistered();
    error LockPeriodNotEnded();
    error AgentAlreadyVerified();
    error VerificationContractNotSet();
    error InvalidZKPProof();
    error TargetAgentNotActive();
    error InvalidMessageCID();
    error InvalidConsumerAddress();
    error CannotCreateServiceForSelf();
    error ConsumerNotActive();
    error ConsumerNotVerified();
    error InvalidPrice();
    error ServiceTypeRequired();
    error PriceTooHigh();
    error NotServiceProvider();
    error ServiceAlreadyCompleted();
    error InvalidResultCID();
    error ServiceNotFound();
    error ServiceExpired();
    error TotalEarningsOverflow();
    error TotalServicesOverflow();
    error ReputationOverflow();
    error InsufficientContractBalance();
    error InvalidReputationScore();
    error FeeRateTooHigh();
    error InvalidVerificationContractAddress();
    error InvalidTreasuryAddress();
    error TreasuryAddressNotSet();
    error NoFeesToWithdraw();
    error AgentNotActive();

    // ============ 枚举定义 ============

    /**
     * @dev 标识符类型枚举
     */
    enum IdentifierType {
        UNKNOWN,      // 未知类型
        IPFS_CID,     // IPFS内容标识符
        IPNS_NAME     // IPNS名称（推荐）
    }

    // ============ 结构体定义 ============

    struct Agent {
        string didDocument;        // DID文档标识符 (优先IPNS名称，兼容IPFS CID)
                                  // IPNS名称不变，可通过重新发布更新指向的内容
                                  // 示例: k51qzi5uqu5dlvj2baxnqndepeb86cbk3ng7n3i46uzyxzyqj2xjonzllnv0v8
        string publicKey;          // 公钥
        uint128 stakedAmount;     // 质押代币数量 (打包优化)
        uint128 totalEarnings;    // 总收益 (打包优化)
        uint64 reputation;        // 声誉分数 (0-65535，打包优化)
        uint64 registrationTime;  // 注册时间 (打包优化)
        uint64 lastActivity;      // 最后活动时间 (打包优化)
        uint32 totalServices;     // 提供服务次数 (打包优化)
        bool isActive;            // 是否活跃 (打包优化)
        bool isVerified;          // 是否通过ZKP验证 (打包优化)
        // ERC-4337 支持
        address aaAccount;        // ERC-4337 账户地址
        bool isAAAccount;         // 是否使用 AA 账户
    }

    struct Message {
        address fromAgent;
        address toAgent;
        string messageCID;        // IPFS消息CID
        uint256 timestamp;
        bool isVerified;          // ZKP验证状态
        uint256 fee;             // 消息费用
    }

    struct Service {
        address provider;
        address consumer;
        string serviceType;       // 服务类型
        uint256 price;           // 服务价格
        uint256 timestamp;
        bool isCompleted;        // 是否完成
        string resultCID;        // 结果CID
    }

    // ============ 状态变量 ============

    IERC20 public token; // DIAP代币合约
    address public verification; // DIAPVerification合约地址
    address public accountFactory; // DIAPAccountFactory合约地址

    mapping(address => Agent) public agents;
    mapping(string => address) public didToAgent;  // DID标识符到地址映射 (支持IPNS名称和IPFS CID)
    mapping(bytes32 => Message) public messages;
    mapping(uint256 => Service) public services;

    // Gas优化：可枚举的智能体列表
    address[] public agentList;
    mapping(address => uint256) public agentIndex; // 智能体地址到索引的映射

    uint256 public totalAgents;
    uint256 public totalMessages;
    uint256 public totalServices;
    uint256 public totalVolume;  // 总交易量

    // 网络参数
    uint256 public registrationFee;     // 注册费用
    uint256 public messageFee;          // 消息费用
    uint256 public serviceFeeRate;      // 服务费用率 (基点)
    uint256 public minStakeAmount;      // 最小质押数量
    uint256 public reputationThreshold; // 声誉阈值
    uint256 public lockPeriod;          // 锁定期
    uint256 public totalStaked;         // 总质押量

    // 奖励参数
    uint256 public rewardRate;          // 奖励率
    uint256 public lastRewardTime;      // 上次奖励时间
    uint256 public totalRewards;        // 总奖励

    // Gas优化：分批奖励分配
    uint256 public constant BATCH_SIZE = 50; // 每批处理的智能体数量
    uint256 public lastProcessedIndex;       // 上次处理的索引
    uint256 public pendingRewards;           // 待分配奖励

    // 混合存储：链上存储关键数据，链下存储详细数据
    mapping(address => string) public agentMetadataCID; // 智能体详细元数据CID（链下）
    mapping(uint256 => string) public serviceMetadataCID; // 服务详细元数据CID（链下）

    // 费用分配
    uint256 public accumulatedFees;  // 累积的注册费和消息费
    address public treasuryAddress;  // 金库地址

    // ============ 事件定义 ============

    event AgentRegistered(
        address indexed agent, 
        string didDocument,  // 支持IPNS名称和IPFS CID
        uint256 stakedAmount
    );

    event AgentRegisteredWithIPNS(
        address indexed agent,
        string ipnsName,
        uint256 stakedAmount,
        uint256 timestamp
    );

    event AgentUnstaked(
        address indexed agent,
        uint256 stakedAmount
    );

    event AgentVerified(
        address indexed agent, 
        bool isVerified
    );

    event MessageSent(
        bytes32 indexed messageId, 
        address from, 
        address to, 
        uint256 fee
    );

    event ServiceCreated(
        uint256 indexed serviceId, 
        address provider, 
        address consumer, 
        uint256 price
    );

    event ServiceCompleted(
        uint256 indexed serviceId, 
        string resultCID, 
        uint256 reward
    );

    event ReputationUpdated(
        address indexed agent, 
        uint256 oldReputation, 
        uint256 newReputation
    );

    event RewardsDistributed(
        uint256 totalAmount, 
        uint256 timestamp
    );

    event FeesWithdrawn(
        address indexed to,
        uint256 amount,
        uint256 timestamp
    );

    event TreasuryAddressUpdated(
        address indexed oldAddress,
        address indexed newAddress
    );

    event AAAccountCreated(
        address indexed agent,
        address indexed aaAccount,
        uint256 timestamp
    );

    event AccountFactoryUpdated(
        address indexed oldFactory,
        address indexed newFactory
    );

    // ============ 修饰符 ============

    modifier onlyRegisteredAgent() {
        if (!agents[msg.sender].isActive) revert AgentNotRegistered();
        _;
    }

    modifier onlyVerifiedAgent() {
        if (!agents[msg.sender].isVerified) revert AgentNotActive();
        _;
    }

    modifier validReputation(uint256 reputation) {
        if (reputation > 10000) revert InvalidReputationScore();
        _;
    }

    // ============ 初始化函数 ============

    function initialize(address _token) public initializer {
        if (_token == address(0)) revert InvalidTokenAddress();

        __Ownable_init();
        __UUPSUpgradeable_init();
        __ReentrancyGuard_init();
        __Pausable_init();

        // 设置代币合约
        token = IERC20(_token);

        // 设置默认参数
        registrationFee = 100 * 10**18;      // 100 代币
        messageFee = 1 * 10**18;             // 1 代币
        serviceFeeRate = 300;                // 3%
        minStakeAmount = 1000 * 10**18;      // 1000 代币
        reputationThreshold = 1000;          // 1000 声誉点
        lockPeriod = 30 days;                // 30天锁定期
        rewardRate = 5;                      // 5% 年化
        lastRewardTime = block.timestamp;
        totalStaked = 0;                     // 初始总质押量为0
    }

    // ============ 智能体管理 ============

    /**
     * @dev 注册智能体（传统 EOA 方式）
     * @param didDocument DID文档标识符 (推荐使用IPNS名称，兼容IPFS CID)
     *                    IPNS名称是不变的根域名，内容更新时无需修改链上标识符
     *                    示例: k51qzi5uqu5dlvj2baxnqndepeb86cbk3ng7n3i46uzyxzyqj2xjonzllnv0v8
     * @param publicKey 公钥
     * @param stakedAmount 质押代币数量
     */
    function registerAgent(
        string calldata didDocument,
        string calldata publicKey,
        uint256 stakedAmount
    ) external nonReentrant whenNotPaused {
        _registerAgent(msg.sender, didDocument, publicKey, stakedAmount, address(0), false);
    }

    /**
     * @dev 注册智能体（ERC-4337 AA 账户方式）
     * @param didDocument DID文档标识符
     * @param publicKey 公钥
     * @param stakedAmount 质押代币数量
     * @param salt 用于创建 AA 账户的盐值
     */
    function registerAgentWithAA(
        string calldata didDocument,
        string calldata publicKey,
        uint256 stakedAmount,
        uint256 salt
    ) external nonReentrant whenNotPaused returns (address aaAccount) {
        require(accountFactory != address(0), "Account factory not set");

        // 调用工厂创建 AA 账户
        // solhint-disable-next-line avoid-low-level-calls
        (bool success, bytes memory data) = accountFactory.call(
            abi.encodeWithSignature("createAccount(address,uint256)", msg.sender, salt)
        );
        require(success, "Failed to create AA account");
        // createAccount 返回 DIAPAccount 合约实例，需要转换为地址
        aaAccount = address(abi.decode(data, (address)));

        // 注册智能体
        _registerAgent(msg.sender, didDocument, publicKey, stakedAmount, aaAccount, true);

        emit AAAccountCreated(msg.sender, aaAccount, block.timestamp);

        return aaAccount;
    }

    /**
     * @dev 内部注册函数
     */
    function _registerAgent(
        address agentAddress,
        string calldata didDocument,
        string calldata publicKey,
        uint256 stakedAmount,
        address aaAccount,
        bool isAA
    ) internal {
        if (agents[agentAddress].isActive) revert AgentAlreadyRegistered();
        if (stakedAmount < minStakeAmount) revert InsufficientStakeAmount();
        if (stakedAmount > type(uint128).max) revert StakeAmountTooLarge();
        if (bytes(didDocument).length == 0) revert InvalidDIDDocument();
        if (!_isValidIdentifier(didDocument)) revert InvalidIdentifierFormat();

        // 优先使用IPNS，检查标识符类型
        IdentifierType idType = _getIdentifierType(didDocument);
        if (idType != IdentifierType.IPNS_NAME && idType != IdentifierType.IPFS_CID) revert MustUseIPNSOrIPFS();

        if (didToAgent[didDocument] != address(0)) revert DIDAlreadyExists();

        // 计算总费用（质押金额 + 注册费用）
        uint256 totalCost = stakedAmount + registrationFee;

        // 确定代币转移的目标地址
        address tokenDestination = isAA ? aaAccount : address(this);

        // 检查代币余额和授权
        if (token.balanceOf(msg.sender) < totalCost) revert InsufficientTokenBalance();
        if (token.allowance(msg.sender, address(this)) < totalCost) revert InsufficientTokenAllowance();

        // 转移注册费到合约
        if (!token.transferFrom(msg.sender, address(this), registrationFee)) revert TokenTransferFailed();
        accumulatedFees += registrationFee;

        // 转移质押代币（EOA 到合约，AA 到 AA 账户）
        if (!token.transferFrom(msg.sender, tokenDestination, stakedAmount)) revert TokenTransferFailed();

        // 创建智能体
        agents[agentAddress] = Agent({
            didDocument: didDocument,
            publicKey: publicKey,
            stakedAmount: uint128(stakedAmount),
            totalEarnings: 0,
            reputation: 1000,
            registrationTime: uint64(block.timestamp),
            lastActivity: uint64(block.timestamp),
            totalServices: 0,
            isActive: true,
            isVerified: false,
            aaAccount: aaAccount,
            isAAAccount: isAA
        });

        didToAgent[didDocument] = agentAddress;

        // Gas优化：维护可枚举列表
        agentIndex[agentAddress] = agentList.length;
        agentList.push(agentAddress);

        totalAgents++;
        totalStaked += stakedAmount;

        emit AgentRegistered(agentAddress, didDocument, stakedAmount);
    }

    /**
     * @dev 取消注册智能体并提取质押代币
     */
    function unstakeAgent() external nonReentrant {
        Agent storage agent = agents[msg.sender];
        if (!agent.isActive) revert AgentNotRegistered();
        if (block.timestamp < agent.registrationTime + lockPeriod) revert LockPeriodNotEnded();

        uint256 stakedAmount = agent.stakedAmount;

        // 标记智能体为非活跃
        agent.isActive = false;

        // Gas优化：从可枚举列表中移除（使用swap-and-pop模式）
        uint256 index = agentIndex[msg.sender];
        uint256 lastIndex = agentList.length - 1;
        if (index != lastIndex) {
            address lastAgent = agentList[lastIndex];
            agentList[index] = lastAgent;
            agentIndex[lastAgent] = index;
        }
        agentList.pop();
        delete agentIndex[msg.sender];

        totalAgents--;
        totalStaked -= stakedAmount;

        // 返还质押代币
        if (!token.transfer(msg.sender, stakedAmount)) revert TokenTransferFailed();

        emit AgentUnstaked(msg.sender, stakedAmount);
    }

    /**
     * @dev 验证智能体身份 (通过ZKP)
     * @param agent 智能体地址
     * @param proof ZKP证明
     */
    function verifyAgent(
        address agent,
        uint256[8] calldata proof
    ) external onlyOwner {
        if (!agents[agent].isActive) revert AgentNotRegistered();
        if (agents[agent].isVerified) revert AgentAlreadyVerified();

        // 调用DIAPVerification合约进行实际验证
        // 这里需要先检查verification合约是否已设置
        if (address(verification) == address(0)) revert VerificationContractNotSet();

        // 通过verification合约验证身份
        // 注意：这里需要verification合约提供相应的验证接口
        bool isValid = _verifyAgentThroughVerification(agent, proof);
        if (!isValid) revert InvalidZKPProof();

        agents[agent].isVerified = true;
        agents[agent].reputation += 1000; // 验证奖励

        emit AgentVerified(agent, true);
        emit ReputationUpdated(agent, agents[agent].reputation - 1000, agents[agent].reputation);
    }

    /**
     * @dev 发送消息
     * @param toAgent 接收方智能体
     * @param messageCID 消息CID
     */
    function sendMessage(
        address toAgent,
        string calldata messageCID
    ) external onlyRegisteredAgent nonReentrant {
        if (!agents[toAgent].isActive) revert TargetAgentNotActive();
        if (bytes(messageCID).length == 0) revert InvalidMessageCID();

        // 检查代币余额和授权
        if (token.balanceOf(msg.sender) < messageFee) revert InsufficientTokenBalance();
        if (token.allowance(msg.sender, address(this)) < messageFee) revert InsufficientTokenAllowance();

        // 转移消息费用
        if (!token.transferFrom(msg.sender, address(this), messageFee)) revert TokenTransferFailed();

        // 累积消息费
        accumulatedFees += messageFee;

        bytes32 messageId = keccak256(abi.encodePacked(
            msg.sender,
            toAgent,
            messageCID,
            block.timestamp
        ));

        messages[messageId] = Message({
            fromAgent: msg.sender,
            toAgent: toAgent,
            messageCID: messageCID,
            timestamp: block.timestamp,
            isVerified: false,
            fee: messageFee
        });

        totalMessages++;
        totalVolume += messageFee;

        // 更新活动时间
        agents[msg.sender].lastActivity = uint64(block.timestamp);
        agents[toAgent].lastActivity = uint64(block.timestamp);

        emit MessageSent(messageId, msg.sender, toAgent, messageFee);
    }

    /**
     * @dev 创建服务
     * @param consumer 消费者地址
     * @param serviceType 服务类型
     * @param price 服务价格
     */
    function createService(
        address consumer,
        string calldata serviceType,
        uint256 price
    ) external onlyVerifiedAgent nonReentrant whenNotPaused {
        if (consumer == address(0)) revert InvalidConsumerAddress();
        if (consumer == msg.sender) revert CannotCreateServiceForSelf();
        if (!agents[consumer].isActive) revert ConsumerNotActive();
        if (!agents[consumer].isVerified) revert ConsumerNotVerified();
        if (price == 0) revert InvalidPrice();
        if (bytes(serviceType).length == 0) revert ServiceTypeRequired();

        // 检查服务价格是否在合理范围内
        if (price > 1000000 * 10**18) revert PriceTooHigh(); // 最大100万代币

        uint256 serviceId = totalServices;
        services[serviceId] = Service({
            provider: msg.sender,
            consumer: consumer,
            serviceType: serviceType,
            price: price,
            timestamp: block.timestamp,
            isCompleted: false,
            resultCID: ""
        });

        totalServices++;

        emit ServiceCreated(serviceId, msg.sender, consumer, price);
    }

    /**
     * @dev 完成服务
     * @param serviceId 服务ID
     * @param resultCID 结果CID
     */
    function completeService(
        uint256 serviceId,
        string calldata resultCID
    ) external onlyVerifiedAgent nonReentrant whenNotPaused {
        Service storage service = services[serviceId];
        if (service.provider != msg.sender) revert NotServiceProvider();
        if (service.isCompleted) revert ServiceAlreadyCompleted();
        if (bytes(resultCID).length == 0) revert InvalidResultCID();
        if (service.timestamp == 0) revert ServiceNotFound();

        // 检查服务是否过期（例如30天）
        if (block.timestamp > service.timestamp + 30 days) revert ServiceExpired();

        // 计算奖励和费用
        uint256 reward = service.price * (10000 - serviceFeeRate) / 10000;
        // uint256 fee = service.price - reward; // 费用留在合约中

        // 更新智能体信息（在转账之前，防止重入攻击）
        Agent storage agent = agents[msg.sender];
        uint256 oldReputation = agent.reputation;

        // 安全检查：确保不会溢出
        if (uint256(agent.totalEarnings) + reward > type(uint128).max) revert TotalEarningsOverflow();
        if (agent.totalServices >= type(uint32).max) revert TotalServicesOverflow();
        if (agent.reputation + 10 > type(uint64).max) revert ReputationOverflow();

        // 更新状态（Checks-Effects-Interactions 模式）
        service.isCompleted = true;
        service.resultCID = resultCID;
        agent.totalEarnings += uint128(reward);
        agent.totalServices++;
        agent.reputation += 10; // 完成服务奖励声誉
        totalVolume += service.price;

        // 外部调用放在最后（Interactions）
        // 检查合约代币余额是否足够支付奖励
        if (token.balanceOf(address(this)) >= reward) {
            // 从合约余额支付奖励
            if (!token.transfer(msg.sender, reward)) revert TokenTransferFailed();
        } else {
            // 如果余额不足，需要动态铸造（需要owner权限）
            // 这里简化处理，实际应用中需要更复杂的逻辑
            revert InsufficientContractBalance();
        }

        emit ServiceCompleted(serviceId, resultCID, reward);
        emit ReputationUpdated(msg.sender, oldReputation, agent.reputation);
    }

    // ============ 声誉管理 ============

    /**
     * @dev 更新声誉分数
     * @param agent 智能体地址
     * @param reputationChange 声誉变化
     */
    function updateReputation(
        address agent,
        int256 reputationChange
    ) external onlyOwner validReputation(agents[agent].reputation) {
        uint256 oldReputation = agents[agent].reputation;
        uint256 newReputation;

        if (reputationChange > 0) {
            newReputation = oldReputation + uint256(reputationChange);
            if (newReputation > 10000) newReputation = 10000;
            if (newReputation > type(uint64).max) newReputation = type(uint64).max;
        } else {
            uint256 decrease = uint256(-reputationChange);
            if (decrease >= oldReputation) {
                newReputation = 0;
            } else {
                newReputation = oldReputation - decrease;
            }
        }

        agents[agent].reputation = uint64(newReputation);
        emit ReputationUpdated(agent, oldReputation, newReputation);
    }

    // ============ 奖励分配 ============

    /**
     * @dev 分配奖励（使用代币而非ETH）
     */
    function distributeRewards() external onlyOwner {
        uint256 timeElapsed = block.timestamp - lastRewardTime;
        uint256 currentTotalStaked = _getTotalStaked();

        if (currentTotalStaked > 0 && timeElapsed > 0) {
            uint256 rewards = currentTotalStaked * rewardRate * timeElapsed / (365 days * 10000);

            // 检查合约代币余额是否足够
            if (rewards > 0 && token.balanceOf(address(this)) >= rewards + currentTotalStaked) {
                _distributeRewardsToStakers(rewards);
                totalRewards += rewards;
                lastRewardTime = block.timestamp;

                emit RewardsDistributed(rewards, block.timestamp);
            }
        }
    }

    // ============ 内部函数 ============

    /**
     * @dev 验证标识符格式是否有效
     * @param identifier 标识符字符串
     * @return 是否有效
     */
    function _isValidIdentifier(string memory identifier) internal pure returns (bool) {
        bytes memory b = bytes(identifier);
        uint256 len = b.length;

        // 长度检查：最小10字符，最大100字符
        if (len < 10 || len > 100) return false;

        // 检查是否以有效前缀开头
        if (len >= 2) {
            // CIDv0: Qm
            if (b[0] == 'Q' && b[1] == 'm') return true;

            // CIDv1: bafy, bafk, bafz
            if (len >= 4 && b[0] == 'b' && b[1] == 'a' && b[2] == 'f') return true;

            // IPNS: k (base36编码的PeerID)
            if (b[0] == 'k' && len >= 50) return true;
        }

        return false;
    }

    /**
     * @dev 获取标识符类型
     * @param identifier 标识符字符串
     * @return 标识符类型
     */
    function _getIdentifierType(string memory identifier) internal pure returns (IdentifierType) {
        bytes memory b = bytes(identifier);
        uint256 len = b.length;

        if (len < 2) return IdentifierType.UNKNOWN;

        // IPNS 名称检测 (k开头，长度50-65)
        if (b[0] == 'k' && len >= 50 && len <= 65) {
            return IdentifierType.IPNS_NAME;
        }

        // IPFS CID 检测
        if ((b[0] == 'Q' && b[1] == 'm') || 
            (len >= 4 && b[0] == 'b' && b[1] == 'a' && b[2] == 'f')) {
            return IdentifierType.IPFS_CID;
        }

        return IdentifierType.UNKNOWN;
    }

    function _verifyZKProof(uint256[8] calldata proof) internal pure returns (bool) {
        // 这里应该集成实际的Noir ZKP验证逻辑
        // 简化实现，实际需要调用ZKP验证合约
        return proof.length == 8 && proof[0] != 0;
    }

    function _getTotalStaked() internal view returns (uint256) {
        return totalStaked;
    }

    function _distributeRewardsToStakers(uint256 rewardsAmount) internal {
        // 根据质押比例分配奖励
        if (totalStaked == 0) return;

        // 将奖励加入待分配池
        pendingRewards += rewardsAmount;
        emit RewardsDistributed(rewardsAmount, block.timestamp);
    }

    /**
     * @dev 分批处理奖励分配（Gas优化）
     * @return 是否完成所有分配
     */
    function processRewardBatch() external onlyOwner returns (bool) {
        if (pendingRewards == 0 || totalStaked == 0) return true;

        uint256 startIndex = lastProcessedIndex;
        uint256 endIndex = startIndex + BATCH_SIZE;
        if (endIndex > agentList.length) {
            endIndex = agentList.length;
        }

        uint256 processedRewards = 0;

        for (uint256 i = startIndex; i < endIndex;) {
            address agentAddr = agentList[i];
            Agent storage agent = agents[agentAddr];

            if (agent.isActive && agent.stakedAmount > 0) {
                // 按质押比例分配奖励
                uint256 agentReward = (pendingRewards * agent.stakedAmount) / totalStaked;
                if (agentReward > 0) {
                    // 这里可以实际转移代币或记录待领取奖励
                    // 为了简化，这里只是记录
                    processedRewards += agentReward;
                }
            }
            unchecked {
                ++i;  // Gas 优化
            }
        }

        lastProcessedIndex = endIndex;

        // 如果处理完所有智能体，重置状态
        if (endIndex >= agentList.length) {
            pendingRewards = 0;
            lastProcessedIndex = 0;
            return true;
        }

        return false;
    }

    /**
     * @dev 通过验证合约验证智能体
     * @param proof ZKP证明
     * @return 是否验证成功
     */
    function _verifyAgentThroughVerification(
        address /* agent */,
        uint256[8] calldata proof
    ) internal pure returns (bool) {
        // 这里应该调用DIAPVerification合约的验证函数
        // 由于接口复杂性，这里使用简化实现
        // 实际应用中需要定义相应的接口
        return proof.length == 8 && proof[0] != 0;
    }

    // ============ 管理函数 ============

    function setRegistrationFee(uint256 _fee) external onlyOwner {
        registrationFee = _fee;
    }

    function setMessageFee(uint256 _fee) external onlyOwner {
        messageFee = _fee;
    }

    function setServiceFeeRate(uint256 _rate) external onlyOwner {
        if (_rate > 1000) revert FeeRateTooHigh(); // 最大10%
        serviceFeeRate = _rate;
    }

    function setMinStakeAmount(uint256 _amount) external onlyOwner {
        minStakeAmount = _amount;
    }

    function setRewardRate(uint256 _rate) external onlyOwner {
        rewardRate = _rate;
    }

    function setVerificationContract(address _verification) external onlyOwner {
        if (_verification == address(0)) revert InvalidVerificationContractAddress();
        verification = _verification;
    }

    /**
     * @dev 设置账户工厂地址
     * @param _factory 工厂地址
     */
    function setAccountFactory(address _factory) external onlyOwner {
        require(_factory != address(0), "Invalid factory address");
        address oldFactory = accountFactory;
        accountFactory = _factory;
        emit AccountFactoryUpdated(oldFactory, _factory);
    }

    /**
     * @dev 设置金库地址
     * @param _treasury 金库地址
     */
    function setTreasuryAddress(address _treasury) external onlyOwner {
        if (_treasury == address(0)) revert InvalidTreasuryAddress();
        address oldTreasury = treasuryAddress;
        treasuryAddress = _treasury;
        emit TreasuryAddressUpdated(oldTreasury, _treasury);
    }

    /**
     * @dev 提取累积的费用到金库
     */
    function withdrawFees() external onlyOwner nonReentrant {
        if (treasuryAddress == address(0)) revert TreasuryAddressNotSet();
        if (accumulatedFees == 0) revert NoFeesToWithdraw();

        uint256 amount = accumulatedFees;
        accumulatedFees = 0;

        if (!token.transfer(treasuryAddress, amount)) revert TokenTransferFailed();

        emit FeesWithdrawn(treasuryAddress, amount, block.timestamp);
    }

    /**
     * @dev 设置智能体元数据CID（混合存储）
     * @param agent 智能体地址
     * @param metadataCID 元数据CID
     */
    function setAgentMetadataCID(address agent, string calldata metadataCID) external onlyOwner {
        if (!agents[agent].isActive) revert AgentNotActive();
        agentMetadataCID[agent] = metadataCID;
    }

    /**
     * @dev 设置服务元数据CID（混合存储）
     * @param serviceId 服务ID
     * @param metadataCID 元数据CID
     */
    function setServiceMetadataCID(uint256 serviceId, string calldata metadataCID) external onlyOwner {
        if (services[serviceId].timestamp == 0) revert ServiceNotFound();
        serviceMetadataCID[serviceId] = metadataCID;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ 查询函数 ============

    function getAgent(address agent) external view returns (Agent memory) {
        return agents[agent];
    }

    function getMessage(bytes32 messageId) external view returns (Message memory) {
        return messages[messageId];
    }

    function getService(uint256 serviceId) external view returns (Service memory) {
        return services[serviceId];
    }

    function getNetworkStats() external view returns (
        uint256 _totalAgents,
        uint256 _totalMessages,
        uint256 _totalServices,
        uint256 _totalVolume,
        uint256 _totalRewards
    ) {
        return (totalAgents, totalMessages, totalServices, totalVolume, totalRewards);
    }

    /**
     * @dev 获取智能体标识符类型
     * @param agent 智能体地址
     * @return 标识符类型 (UNKNOWN, IPFS_CID, IPNS_NAME)
     */
    function getAgentIdentifierType(address agent) external view returns (IdentifierType) {
        if (!agents[agent].isActive) revert AgentNotRegistered();
        return _getIdentifierType(agents[agent].didDocument);
    }

    /**
     * @dev 获取智能体的 AA 账户地址
     * @param agent 智能体地址
     * @return AA 账户地址（如果没有则返回 address(0)）
     */
    function getAgentAAAccount(address agent) external view returns (address) {
        return agents[agent].aaAccount;
    }

    /**
     * @dev 检查智能体是否使用 AA 账户
     * @param agent 智能体地址
     * @return 是否使用 AA 账户
     */
    function isAgentUsingAA(address agent) external view returns (bool) {
        return agents[agent].isAAAccount;
    }

    /**
     * @dev 获取智能体的代币余额（支持 AA 账户）
     * @param agent 智能体地址
     * @return 代币余额
     */
    function getAgentTokenBalance(address agent) external view returns (uint256) {
        if (!agents[agent].isActive) revert AgentNotRegistered();

        if (agents[agent].isAAAccount && agents[agent].aaAccount != address(0)) {
            // 如果是 AA 账户，返回 AA 账户的余额
            return token.balanceOf(agents[agent].aaAccount);
        } else {
            // 如果是 EOA，返回 EOA 的余额
            return token.balanceOf(agent);
        }
    }

    /**
     * @dev 验证调用者（支持 AA 账户）
     * @param agent 智能体地址
     * @param caller 调用者地址
     * @return 是否有效
     */
    function isValidCaller(address agent, address caller) external view returns (bool) {
        if (!agents[agent].isActive) return false;

        // 如果是 EOA，调用者必须是智能体本身
        if (!agents[agent].isAAAccount) {
            return caller == agent;
        }

        // 如果是 AA 账户，调用者可以是 AA 账户或智能体本身
        return caller == agents[agent].aaAccount || caller == agent;
    }


    // 接收ETH
    receive() external payable {}
}

contracts/DIAPGovernance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;


import "@openzeppelin/contracts/governance/Governor.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorVotes.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorVotesQuorumFraction.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorTimelockControl.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorSettings.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorCountingSimple.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./DIAPToken.sol";
import "./DIAPAgentNetwork.sol";

/**
 * @title DIAPGovernance
 * @dev DIAP智能体网络治理合约
 * @notice 基于OpenZeppelin Governor实现去中心化治理
 */
contract DIAPGovernance is 
    Governor,
    GovernorVotes,
    GovernorVotesQuorumFraction,
    GovernorTimelockControl,
    GovernorSettings,
    GovernorCountingSimple,
    Ownable
{
    
    // ============ Custom Errors ============
    
    error NotAuthorizedToCreateProposals();
    error NotAuthorizedForEmergencyActions();
    error EmergencyActionFailed();
    error InvalidMultisigWalletAddress();
    error NotAuthorized();
    error NotAuthorizedForUpgrade();
    error TotalVotesOverflow();
    error ReputationVotesOverflow();
    
    // ============ 提案类型 ============
    
    enum ProposalType {
        NETWORK_UPGRADE,     // 网络升级
        PARAMETER_CHANGE,    // 参数调整
        TREASURY_MANAGEMENT, // 资金管理
        AGENT_POLICY,       // 智能体政策
        TOKEN_ECONOMICS,    // 代币经济
        EMERGENCY_ACTION    // 紧急行动
    }
    
    // ============ 状态变量 ============
    
    DIAPAgentNetwork public agentNetwork;
    
    // 提案类型映射
    mapping(uint256 => ProposalType) public proposalTypes;
    
    // 特殊权限
    mapping(address => bool) public emergencyExecutors;
    mapping(address => bool) public proposalCreators;
    
    // 多签钱包控制升级权限
    address public multisigWallet;
    mapping(address => bool) public upgradeAuthorizers;
    
    // 治理参数
    uint256 public constant PROPOSAL_THRESHOLD = 1000 * 10**18; // 1000代币门槛
    uint256 public constant VOTING_DELAY = 1 days;    // 1天延迟
    uint256 public constant VOTING_PERIOD = 3 days;   // 3天投票期
    uint256 public constant EXECUTION_DELAY = 1 days; // 1天执行延迟
    uint256 public constant QUORUM_FRACTION = 4;      // 4% 法定人数
    
    // 紧急提案参数
    uint256 public constant EMERGENCY_VOTING_PERIOD = 6 hours; // 6小时紧急投票期
    uint256 public constant EMERGENCY_QUORUM_FRACTION = 10;    // 10% 紧急法定人数
    
    // ============ 事件定义 ============
    
    event DIAPProposalCreated(
        uint256 indexed proposalId,
        ProposalType indexed proposalType,
        address indexed proposer,
        string description
    );
    
    event DIAPProposalExecuted(
        uint256 indexed proposalId,
        ProposalType indexed proposalType
    );
    
    event EmergencyActionExecuted(
        address indexed executor,
        string action,
        uint256 timestamp
    );
    
    event GovernanceParameterUpdated(
        string parameter,
        uint256 oldValue,
        uint256 newValue
    );
    
    // ============ 构造函数 ============
    
    constructor(
        IVotes _token,
        TimelockController _timelock,
        DIAPAgentNetwork _agentNetwork
    )
        Governor("DIAP Governance")
        GovernorVotes(_token)
        GovernorVotesQuorumFraction(QUORUM_FRACTION)
        GovernorTimelockControl(_timelock)
        GovernorSettings(
            VOTING_DELAY,
            VOTING_PERIOD,
            PROPOSAL_THRESHOLD
        )
    {
        agentNetwork = _agentNetwork;
        
        // 设置初始权限
        emergencyExecutors[msg.sender] = true;
        proposalCreators[msg.sender] = true;
    }
    
    // ============ 提案创建 ============
    
    /**
     * @dev 创建网络升级提案
     * @param targets 目标合约
     * @param values ETH数量
     * @param calldatas 调用数据
     * @param description 提案描述
     */
    function proposeNetworkUpgrade(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas,
        string calldata description
    ) external returns (uint256) {
        if (!proposalCreators[msg.sender] && !_isVerifiedAgent(msg.sender)) revert NotAuthorizedToCreateProposals();
        
        uint256 proposalId = propose(targets, values, calldatas, description);
        proposalTypes[proposalId] = ProposalType.NETWORK_UPGRADE;
        
        emit DIAPProposalCreated(proposalId, ProposalType.NETWORK_UPGRADE, msg.sender, description);
        return proposalId;
    }
    
    /**
     * @dev 创建参数调整提案
     * @param targets 目标合约
     * @param values ETH数量
     * @param calldatas 调用数据
     * @param description 提案描述
     */
    function proposeParameterChange(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas,
        string calldata description
    ) external returns (uint256) {
        if (!proposalCreators[msg.sender] && !_isVerifiedAgent(msg.sender)) revert NotAuthorizedToCreateProposals();
        
        uint256 proposalId = propose(targets, values, calldatas, description);
        proposalTypes[proposalId] = ProposalType.PARAMETER_CHANGE;
        
        emit DIAPProposalCreated(proposalId, ProposalType.PARAMETER_CHANGE, msg.sender, description);
        return proposalId;
    }
    
    /**
     * @dev 创建资金管理提案
     * @param targets 目标合约
     * @param values ETH数量
     * @param calldatas 调用数据
     * @param description 提案描述
     */
    function proposeTreasuryManagement(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas,
        string calldata description
    ) external returns (uint256) {
        if (!proposalCreators[msg.sender] && !_isVerifiedAgent(msg.sender)) revert NotAuthorizedToCreateProposals();
        
        uint256 proposalId = propose(targets, values, calldatas, description);
        proposalTypes[proposalId] = ProposalType.TREASURY_MANAGEMENT;
        
        emit DIAPProposalCreated(proposalId, ProposalType.TREASURY_MANAGEMENT, msg.sender, description);
        return proposalId;
    }
    
    /**
     * @dev 创建智能体政策提案
     * @param targets 目标合约
     * @param values ETH数量
     * @param calldatas 调用数据
     * @param description 提案描述
     */
    function proposeAgentPolicy(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas,
        string calldata description
    ) external returns (uint256) {
        if (!proposalCreators[msg.sender] && !_isVerifiedAgent(msg.sender)) revert NotAuthorizedToCreateProposals();
        
        uint256 proposalId = propose(targets, values, calldatas, description);
        proposalTypes[proposalId] = ProposalType.AGENT_POLICY;
        
        emit DIAPProposalCreated(proposalId, ProposalType.AGENT_POLICY, msg.sender, description);
        return proposalId;
    }
    
    /**
     * @dev 创建代币经济提案
     * @param targets 目标合约
     * @param values ETH数量
     * @param calldatas 调用数据
     * @param description 提案描述
     */
    function proposeTokenEconomics(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas,
        string calldata description
    ) external returns (uint256) {
        if (!proposalCreators[msg.sender] && !_isVerifiedAgent(msg.sender)) revert NotAuthorizedToCreateProposals();
        
        uint256 proposalId = propose(targets, values, calldatas, description);
        proposalTypes[proposalId] = ProposalType.TOKEN_ECONOMICS;
        
        emit DIAPProposalCreated(proposalId, ProposalType.TOKEN_ECONOMICS, msg.sender, description);
        return proposalId;
    }
    
    /**
     * @dev 创建紧急行动提案
     * @param targets 目标合约
     * @param values ETH数量
     * @param calldatas 调用数据
     * @param description 提案描述
     */
    function proposeEmergencyAction(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas,
        string calldata description
    ) external returns (uint256) {
        if (!emergencyExecutors[msg.sender]) revert NotAuthorizedForEmergencyActions();
        
        uint256 proposalId = propose(targets, values, calldatas, description);
        proposalTypes[proposalId] = ProposalType.EMERGENCY_ACTION;
        
        emit DIAPProposalCreated(proposalId, ProposalType.EMERGENCY_ACTION, msg.sender, description);
        return proposalId;
    }
    
    // ============ 投票功能 ============
    
    /**
     * @dev 获取投票权重 (代币 + 声誉)
     * @param account 账户地址
     * @param blockNumber 区块号
     * @return 投票权重
     */
    function getVotes(address account, uint256 blockNumber) 
        public view override(IGovernor, Governor) returns (uint256) {
        
        // 基础代币投票权重
        uint256 tokenVotes = token.getPastVotes(account, blockNumber);
        
        // 声誉投票权重 (如果智能体网络可用)
        uint256 reputationVotes = 0;
        try agentNetwork.getAgent(account) returns (DIAPAgentNetwork.Agent memory agent) {
            if (agent.isActive && agent.isVerified) {
                // 使用平方根转换防止巨鲸控制，并添加溢出保护
                uint256 reputation = agent.reputation;
                if (reputation > 0) {
                    // reputation最大10000，sqrt(10000) = 100
                    // 乘以10**15确保有足够的精度，但不会溢出
                    uint256 sqrtReputation = _sqrt(reputation);
                    // 限制最大声誉投票权重，防止溢出
                    reputationVotes = sqrtReputation * 10**15;
                    // 确保不会溢出
                    if (reputationVotes / 10**15 != sqrtReputation) revert ReputationVotesOverflow();
                }
            }
        } catch {
            // 如果智能体网络不可用，只使用代币投票
        }
        
        // 检查总和不会溢出
        if (tokenVotes > type(uint256).max - reputationVotes) revert TotalVotesOverflow();
        
        return tokenVotes + reputationVotes;
    }
    
    /**
     * @dev 计算平方根（Babylonian方法）
     * @param x 输入值
     * @return y 平方根
     */
    function _sqrt(uint256 x) internal pure returns (uint256 y) {
        if (x == 0) return 0;
        uint256 z = (x + 1) / 2;
        y = x;
        while (z < y) {
            y = z;
            z = (x / z + z) / 2;
        }
    }
    
    /**
     * @dev 获取当前投票权重
     * @param account 账户地址
     * @return 投票权重
     */
    function getCurrentVotes(address account) external view returns (uint256) {
        return getVotes(account, block.number - 1);
    }
    
    // ============ 提案执行 ============
    
    /**
     * @dev 执行提案
     * @param targets 目标合约
     * @param values ETH数量
     * @param calldatas 调用数据
     * @param descriptionHash 描述哈希
     */
    function execute(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) public payable override(IGovernor, Governor) returns (uint256) {
        uint256 proposalId = super.execute(targets, values, calldatas, descriptionHash);
        
        // 发出提案执行事件
        ProposalType proposalType = proposalTypes[proposalId];
        emit DIAPProposalExecuted(proposalId, proposalType);
        
        return proposalId;
    }
    
    // ============ 紧急功能 ============
    
    /**
     * @dev 执行紧急行动
     * @param action 行动描述
     * @param targets 目标合约
     * @param values ETH数量
     * @param calldatas 调用数据
     */
    function executeEmergencyAction(
        string calldata action,
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata calldatas
    ) external {
        if (!emergencyExecutors[msg.sender]) revert NotAuthorizedForEmergencyActions();
        
        // 执行紧急行动
        for (uint256 i = 0; i < targets.length;) {
            (bool success, ) = targets[i].call{value: values[i]}(calldatas[i]);
            if (!success) revert EmergencyActionFailed();
            unchecked {
                ++i;  // Gas 优化
            }
        }
        
        emit EmergencyActionExecuted(msg.sender, action, block.timestamp);
    }
    
    // ============ 管理函数 ============
    
    /**
     * @dev 设置紧急执行者
     * @param executor 执行者地址
     * @param authorized 是否授权
     */
    function setEmergencyExecutor(address executor, bool authorized) external onlyOwner {
        emergencyExecutors[executor] = authorized;
    }
    
    /**
     * @dev 设置提案创建者
     * @param creator 创建者地址
     * @param authorized 是否授权
     */
    function setProposalCreator(address creator, bool authorized) external onlyOwner {
        proposalCreators[creator] = authorized;
    }
    
    /**
     * @dev 设置多签钱包地址
     * @param _multisigWallet 多签钱包地址
     */
    function setMultisigWallet(address _multisigWallet) external onlyOwner {
        if (_multisigWallet == address(0)) revert InvalidMultisigWalletAddress();
        multisigWallet = _multisigWallet;
    }
    
    /**
     * @dev 设置升级授权者
     * @param authorizer 授权者地址
     * @param authorized 是否授权
     */
    function setUpgradeAuthorizer(address authorizer, bool authorized) external {
        if (msg.sender != multisigWallet && msg.sender != owner()) revert NotAuthorized();
        upgradeAuthorizers[authorizer] = authorized;
    }
    
    /**
     * @dev 检查升级权限（多签控制）
     */
    function _authorizeUpgrade(address /* newImplementation */) internal view {
        if (!upgradeAuthorizers[msg.sender] && msg.sender != multisigWallet && msg.sender != owner()) revert NotAuthorizedForUpgrade();
        // 注意：DIAPGovernance不是UUPS合约，这里只是权限检查
    }
    
    /**
     * @dev 更新治理参数
     * @param parameter 参数名称
     * @param newValue 新值
     */
    function updateGovernanceParameter(string calldata parameter, uint256 newValue) external onlyOwner {
        // 这里可以根据需要添加更多参数更新逻辑
        emit GovernanceParameterUpdated(parameter, 0, newValue);
    }
    
    // ============ 查询函数 ============
    
    /**
     * @dev 获取提案信息
     * @param proposalId 提案ID
     * @return proposalType 提案类型
     * @return proposalState 提案状态
     * @return forVotes 赞成票数
     * @return againstVotes 反对票数
     * @return abstainVotes 弃权票数
     */
    function getProposalInfo(uint256 proposalId) external view returns (
        ProposalType proposalType,
        ProposalState proposalState,
        uint256 forVotes,
        uint256 againstVotes,
        uint256 abstainVotes
    ) {
        proposalType = proposalTypes[proposalId];
        proposalState = state(proposalId);
        
        // 获取投票信息 - 使用GovernorCountingSimple的默认实现
        (uint256 forVotes_, uint256 againstVotes_, uint256 abstainVotes_) = proposalVotes(proposalId);
        forVotes = forVotes_;
        againstVotes = againstVotes_;
        abstainVotes = abstainVotes_;
    }
    
    /**
     * @dev 获取治理统计信息
     * @return totalProposals 总提案数
     * @return activeProposals 活跃提案数
     * @return executedProposals 已执行提案数
     */
    function getGovernanceStats() external pure returns (
        uint256 totalProposals,
        uint256 activeProposals,
        uint256 executedProposals
    ) {
        // 这里需要遍历所有提案来计算统计信息
        // 为了gas效率，可以考虑使用链下计算
        return (0, 0, 0);
    }
    
    // ============ 内部函数 ============
    
    /**
     * @dev 检查是否为已验证智能体
     * @param agent 智能体地址
     * @return 是否为已验证智能体
     */
    function _isVerifiedAgent(address agent) internal view returns (bool) {
        try agentNetwork.getAgent(agent) returns (DIAPAgentNetwork.Agent memory agentInfo) {
            return agentInfo.isActive && agentInfo.isVerified;
        } catch {
            return false;
        }
    }
    
    // ============ 重写函数 ============
    
    /**
     * @dev 获取投票延迟
     * @return 投票延迟时间
     */
    function votingDelay() public view override(IGovernor, GovernorSettings) returns (uint256) {
        return super.votingDelay();
    }
    
    /**
     * @dev 获取投票期
     * @return 投票期时间
     */
    function votingPeriod() public view override(IGovernor, GovernorSettings) returns (uint256) {
        return super.votingPeriod();
    }
    
    /**
     * @dev 获取提案门槛
     * @return 提案门槛
     */
    function proposalThreshold() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.proposalThreshold();
    }
    
    /**
     * @dev 获取法定人数
     * @param blockNumber 区块号
     * @return 法定人数
     */
    function quorum(uint256 blockNumber) public view override(IGovernor, GovernorVotesQuorumFraction) returns (uint256) {
        return super.quorum(blockNumber);
    }
    
    /**
     * @dev 重写_cancel函数以解决多重继承冲突
     */
    function _cancel(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint256) {
        return super._cancel(targets, values, calldatas, descriptionHash);
    }
    
    /**
     * @dev 重写_execute函数以解决多重继承冲突
     */
    function _execute(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) {
        super._execute(proposalId, targets, values, calldatas, descriptionHash);
    }
    
    /**
     * @dev 重写_executor函数以解决多重继承冲突
     */
    function _executor() internal view override(Governor, GovernorTimelockControl) returns (address) {
        return super._executor();
    }
    
    /**
     * @dev 重写state函数以解决多重继承冲突
     */
    function state(uint256 proposalId) public view override(Governor, GovernorTimelockControl) returns (ProposalState) {
        return super.state(proposalId);
    }
    
    /**
     * @dev 重写supportsInterface函数以解决多重继承冲突
     */
    function supportsInterface(bytes4 interfaceId) public view override(Governor, GovernorTimelockControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/DIAPPaymentChannel.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "./DIAPToken.sol";
import "./DIAPAgentNetwork.sol";

/**
 * @title DIAPPaymentChannel
 * @dev DIAP支付通道合约 - 状态通道和链下支付
 */
contract DIAPPaymentChannel is
    Initializable,
    UUPSUpgradeable,
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable
{
    // ============ Custom Errors ============

    error DepositMustBeGreaterThanZero();
    error ChannelIDRequired();
    error ChannelAlreadyExists();
    error CannotOpenChannelWithSelf();
    error InvalidParticipantAddress();
    error SenderNotRegistered();
    error Participant2NotRegistered();
    error InsufficientBalance();
    error InsufficientAllowance();
    error TransferFailed();
    error ChannelNotFound();
    error ChannelNotActive();
    error NotChannelParticipant();
    error NonceMustBeGreater();
    error InvalidBalanceDistribution();
    error InvalidSignatures();
    error NoActiveChallengePerio();
    error ChallengePeriodExpired();
    error NewNonceMustBeGreater();
    error ChallengePeriodNotEnded();
    error InsufficientFunds();
    error TransferToParticipant1Failed();
    error TransferToParticipant2Failed();
    error RateTooHigh();

    // ============ 结构体定义 ============

    struct PaymentChannel {
        address participant1;
        address participant2;
        uint256 balance1;
        uint256 balance2;
        uint256 totalDeposited;
        uint256 nonce;
        bool isActive;
        uint256 lastUpdate;
        uint256 challengeDeadline;
        string channelId;
    }

    // ============ 状态变量 ============

    DIAPToken public token;
    DIAPAgentNetwork public agentNetwork;

    mapping(string => PaymentChannel) public paymentChannels;

    uint256 public channelFeeRate;
    uint256 public constant CHALLENGE_PERIOD = 24 hours;

    // solhint-disable-next-line var-name-mixedcase
    bytes32 public DOMAIN_SEPARATOR;
    bytes32 public constant CHANNEL_STATE_TYPEHASH =
        keccak256(
            "ChannelState(string channelId,uint256 balance1,uint256 balance2,uint256 nonce)"
        );

    // ============ 事件定义 ============

    event PaymentChannelOpened(
        string indexed channelId,
        address indexed participant1,
        address indexed participant2,
        uint256 totalDeposit
    );

    event PaymentChannelClosed(
        string indexed channelId,
        uint256 finalBalance1,
        uint256 finalBalance2
    );

    event ChannelChallenged(
        string indexed channelId,
        uint256 newNonce,
        uint256 newBalance1,
        uint256 newBalance2
    );

    // ============ 初始化函数 ============

    function initialize(address _token, address _agentNetwork) public initializer {
        __Ownable_init();
        __UUPSUpgradeable_init();
        __ReentrancyGuard_init();
        __Pausable_init();

        token = DIAPToken(_token);
        agentNetwork = DIAPAgentNetwork(payable(_agentNetwork));

        channelFeeRate = 5; // 0.05%

        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256(
                    "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
                ),
                keccak256(bytes("DIAP Payment Channel")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
    }

    // ============ 支付通道功能 ============

    function openPaymentChannel(
        address participant2,
        uint256 deposit,
        string calldata channelId
    ) external nonReentrant whenNotPaused {
        if (deposit == 0) revert DepositMustBeGreaterThanZero();
        if (bytes(channelId).length == 0) revert ChannelIDRequired();
        if (paymentChannels[channelId].lastUpdate != 0) revert ChannelAlreadyExists();
        if (participant2 == msg.sender) revert CannotOpenChannelWithSelf();
        if (participant2 == address(0)) revert InvalidParticipantAddress();

        if (!agentNetwork.getAgent(msg.sender).isActive) revert SenderNotRegistered();
        if (!agentNetwork.getAgent(participant2).isActive) revert Participant2NotRegistered();

        if (token.balanceOf(msg.sender) < deposit) revert InsufficientBalance();
        if (token.allowance(msg.sender, address(this)) < deposit) revert InsufficientAllowance();

        paymentChannels[channelId] = PaymentChannel({
            participant1: msg.sender,
            participant2: participant2,
            balance1: deposit,
            balance2: 0,
            totalDeposited: deposit,
            nonce: 0,
            isActive: true,
            lastUpdate: block.timestamp,
            challengeDeadline: 0,
            channelId: channelId
        });

        if (!token.transferFrom(msg.sender, address(this), deposit)) revert TransferFailed();

        emit PaymentChannelOpened(channelId, msg.sender, participant2, deposit);
    }

    function initiateChannelClose(
        string calldata channelId,
        uint256 finalBalance1,
        uint256 finalBalance2,
        uint256 nonce,
        bytes calldata signature1,
        bytes calldata signature2
    ) external nonReentrant whenNotPaused {
        PaymentChannel storage channel = paymentChannels[channelId];
        if (channel.lastUpdate == 0) revert ChannelNotFound();
        if (!channel.isActive) revert ChannelNotActive();
        if (msg.sender != channel.participant1 && msg.sender != channel.participant2) revert NotChannelParticipant();

        if (nonce <= channel.nonce) revert NonceMustBeGreater();
        if (finalBalance1 + finalBalance2 > channel.totalDeposited) revert InvalidBalanceDistribution();

        if (!_verifyChannelSignatures(
                channelId,
                finalBalance1,
                finalBalance2,
                nonce,
                channel.participant1,
                channel.participant2,
                signature1,
                signature2
            )) revert InvalidSignatures();

        channel.balance1 = finalBalance1;
        channel.balance2 = finalBalance2;
        channel.nonce = nonce;
        channel.challengeDeadline = block.timestamp + CHALLENGE_PERIOD;

        emit PaymentChannelClosed(channelId, finalBalance1, finalBalance2);
    }

    function challengeChannelClose(
        string calldata channelId,
        uint256 newBalance1,
        uint256 newBalance2,
        uint256 newNonce,
        bytes calldata signature1,
        bytes calldata signature2
    ) external nonReentrant whenNotPaused {
        PaymentChannel storage channel = paymentChannels[channelId];
        if (channel.lastUpdate == 0) revert ChannelNotFound();
        if (!channel.isActive) revert ChannelNotActive();
        if (channel.challengeDeadline == 0) revert NoActiveChallengePerio();
        if (block.timestamp >= channel.challengeDeadline) revert ChallengePeriodExpired();
        if (msg.sender != channel.participant1 && msg.sender != channel.participant2) revert NotChannelParticipant();

        if (newNonce <= channel.nonce) revert NewNonceMustBeGreater();
        if (newBalance1 + newBalance2 > channel.totalDeposited) revert InvalidBalanceDistribution();

        if (!_verifyChannelSignatures(
                channelId,
                newBalance1,
                newBalance2,
                newNonce,
                channel.participant1,
                channel.participant2,
                signature1,
                signature2
            )) revert InvalidSignatures();

        channel.balance1 = newBalance1;
        channel.balance2 = newBalance2;
        channel.nonce = newNonce;

        emit ChannelChallenged(channelId, newNonce, newBalance1, newBalance2);
    }

    function finalizeChannelClose(string calldata channelId) external nonReentrant {
        PaymentChannel storage channel = paymentChannels[channelId];
        if (channel.lastUpdate == 0) revert ChannelNotFound();
        if (!channel.isActive) revert ChannelNotActive();
        if (channel.challengeDeadline == 0) revert NoActiveChallengePerio();
        if (block.timestamp < channel.challengeDeadline) revert ChallengePeriodNotEnded();

        uint256 fee = (channel.totalDeposited * channelFeeRate) / 10000;
        uint256 totalToDistribute = channel.balance1 + channel.balance2;
        if (totalToDistribute + fee > channel.totalDeposited) revert InsufficientFunds();

        if (channel.balance1 > 0) {
            if (!token.transfer(channel.participant1, channel.balance1)) revert TransferToParticipant1Failed();
        }
        if (channel.balance2 > 0) {
            if (!token.transfer(channel.participant2, channel.balance2)) revert TransferToParticipant2Failed();
        }

        channel.isActive = false;
    }

    // ============ 内部函数 ============

    function _verifyChannelSignatures(
        string calldata channelId,
        uint256 balance1,
        uint256 balance2,
        uint256 nonce,
        address participant1,
        address participant2,
        bytes calldata signature1,
        bytes calldata signature2
    ) internal view returns (bool) {
        bytes32 structHash = keccak256(
            abi.encode(
                CHANNEL_STATE_TYPEHASH,
                keccak256(bytes(channelId)),
                balance1,
                balance2,
                nonce
            )
        );

        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash));

        address signer1 = _recoverSigner(digest, signature1);
        address signer2 = _recoverSigner(digest, signature2);

        return
            (signer1 == participant1 && signer2 == participant2) ||
            (signer1 == participant2 && signer2 == participant1);
    }

    function _recoverSigner(
        bytes32 digest,
        bytes calldata signature
    ) internal pure returns (address) {
        require(signature.length == 65, "Invalid signature length");

        bytes32 r;
        bytes32 s;
        uint8 v;

        assembly {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 32))
            v := byte(0, calldataload(add(signature.offset, 64)))
        }

        if (
            uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0
        ) {
            return address(0);
        }

        if (v != 27 && v != 28) {
            return address(0);
        }

        return ecrecover(digest, v, r, s);
    }

    // ============ 管理函数 ============

    function setChannelFeeRate(uint256 _rate) external onlyOwner {
        if (_rate > 100) revert RateTooHigh();
        channelFeeRate = _rate;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ 查询函数 ============

    function getPaymentChannel(
        string calldata channelId
    ) external view returns (PaymentChannel memory) {
        return paymentChannels[channelId];
    }

    receive() external payable {}
}

contracts/DIAPPaymentCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "./DIAPToken.sol";
import "./DIAPAgentNetwork.sol";

/**
 * @title DIAPPaymentCore
 * @dev DIAP核心支付合约 - 基础支付和服务托管
 */
contract DIAPPaymentCore is
    Initializable,
    UUPSUpgradeable,
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable
{
    // ============ Custom Errors ============
    
    error AmountMustBeGreaterThanZero();
    error PaymentIDRequired();
    error PaymentIDAlreadyExists();
    error SenderNotRegistered();
    error RecipientNotRegistered();
    error InsufficientBalance();
    error PaymentNotFound();
    error PaymentNotPending();
    error NotPaymentRecipient();
    error PaymentExpired();
    error InsufficientAllowance();
    error TransferToRecipientFailed();
    error TransferFeeFailed();
    error NotPaymentSender();
    error InvalidProviderAddress();
    error CannotCreateServiceForSelf();
    error InvalidPrice();
    error ServiceTypeCIDRequired();
    error ConsumerNotRegistered();
    error ProviderNotRegistered();
    error TokenTransferFailed();
    error NotServiceProvider();
    error ServiceNotEscrowed();
    error InvalidResultCID();
    error ServiceExpired();
    error TransferToProviderFailed();
    error NotServiceConsumer();
    error CancellationPeriodExpired();
    error RefundTransferFailed();
    error RateTooHigh();
    
    // ============ 结构体定义 ============

    struct Payment {
        address from;
        address to;
        uint256 amount;
        string paymentId;
        string description;
        uint256 timestamp;
        PaymentStatus status;
        string metadata;
    }

    struct Service {
        address provider;
        address consumer;
        uint256 price;
        uint256 escrowedAmount;
        uint256 timestamp;
        uint256 completionTime;
        ServiceStatus status;
        string serviceTypeCID;
        string resultCID;
    }

    enum PaymentStatus {
        PENDING,
        CONFIRMED,
        FAILED,
        CANCELLED
    }

    enum ServiceStatus {
        Created,
        Escrowed,
        Active,
        Completed,
        Cancelled
    }

    // ============ 状态变量 ============

    DIAPToken public token;
    DIAPAgentNetwork public agentNetwork;

    mapping(string => Payment) public payments;
    mapping(uint256 => Service) public services;

    uint256 public totalPayments;
    uint256 public totalServices;
    uint256 public totalVolume;

    uint256 public paymentFeeRate; // 支付费用率 (基点)

    // ============ 事件定义 ============

    event PaymentCreated(
        string indexed paymentId,
        address indexed from,
        address indexed to,
        uint256 amount
    );

    event PaymentConfirmed(string indexed paymentId, uint256 timestamp);

    event PaymentFailed(string indexed paymentId, string reason);

    event ServiceCreated(
        uint256 indexed serviceId,
        address indexed provider,
        address indexed consumer,
        uint256 price
    );

    event ServiceCompleted(
        uint256 indexed serviceId,
        address indexed provider,
        uint256 amount
    );

    event ServiceCancelled(uint256 indexed serviceId, uint256 refundAmount);

    // ============ 初始化函数 ============

    function initialize(address _token, address _agentNetwork) public initializer {
        __Ownable_init();
        __UUPSUpgradeable_init();
        __ReentrancyGuard_init();
        __Pausable_init();

        token = DIAPToken(_token);
        agentNetwork = DIAPAgentNetwork(payable(_agentNetwork));

        paymentFeeRate = 10; // 0.1%
    }

    // ============ 基础支付功能 ============

    function createPayment(
        address to,
        uint256 amount,
        string calldata paymentId,
        string calldata description,
        string calldata metadata
    ) external nonReentrant whenNotPaused {
        if (amount == 0) revert AmountMustBeGreaterThanZero();
        if (bytes(paymentId).length == 0) revert PaymentIDRequired();
        if (payments[paymentId].timestamp != 0) revert PaymentIDAlreadyExists();
        
        // 获取实际的智能体地址（支持 AA 账户调用）
        address actualSender = _getActualAgent(msg.sender);
        address actualRecipient = _getActualAgent(to);
        
        if (!agentNetwork.getAgent(actualSender).isActive) revert SenderNotRegistered();
        if (!agentNetwork.getAgent(actualRecipient).isActive) revert RecipientNotRegistered();

        uint256 fee = (amount * paymentFeeRate) / 10000;
        uint256 totalAmount = amount + fee;

        if (token.balanceOf(msg.sender) < totalAmount) revert InsufficientBalance();

        payments[paymentId] = Payment({
            from: actualSender,
            to: actualRecipient,
            amount: amount,
            paymentId: paymentId,
            description: description,
            timestamp: block.timestamp,
            status: PaymentStatus.PENDING,
            metadata: metadata
        });

        totalPayments++;

        emit PaymentCreated(paymentId, actualSender, actualRecipient, amount);
    }

    function confirmPayment(string calldata paymentId) external nonReentrant whenNotPaused {
        Payment storage payment = payments[paymentId];
        if (payment.timestamp == 0) revert PaymentNotFound();
        if (payment.status != PaymentStatus.PENDING) revert PaymentNotPending();
        if (payment.to != msg.sender) revert NotPaymentRecipient();
        if (block.timestamp > payment.timestamp + 24 hours) revert PaymentExpired();

        uint256 fee = (payment.amount * paymentFeeRate) / 10000;
        uint256 totalAmount = payment.amount + fee;

        if (token.balanceOf(payment.from) < totalAmount) revert InsufficientBalance();
        if (token.allowance(payment.from, address(this)) < totalAmount) revert InsufficientAllowance();

        if (!token.transferFrom(payment.from, payment.to, payment.amount)) revert TransferToRecipientFailed();
        if (fee > 0) {
            if (!token.transferFrom(payment.from, address(this), fee)) revert TransferFeeFailed();
        }

        payment.status = PaymentStatus.CONFIRMED;
        totalVolume += payment.amount;

        emit PaymentConfirmed(paymentId, block.timestamp);
    }

    function cancelPayment(string calldata paymentId) external {
        Payment storage payment = payments[paymentId];
        if (payment.timestamp == 0) revert PaymentNotFound();
        if (payment.status != PaymentStatus.PENDING) revert PaymentNotPending();
        if (payment.from != msg.sender) revert NotPaymentSender();

        payment.status = PaymentStatus.CANCELLED;

        emit PaymentFailed(paymentId, "Cancelled by sender");
    }

    // ============ 服务托管支付功能 ============

    function createServiceOrder(
        address provider,
        string calldata serviceTypeCID,
        uint256 price
    ) external nonReentrant whenNotPaused returns (uint256) {
        if (provider == address(0)) revert InvalidProviderAddress();
        if (provider == msg.sender) revert CannotCreateServiceForSelf();
        if (price == 0) revert InvalidPrice();
        if (bytes(serviceTypeCID).length == 0) revert ServiceTypeCIDRequired();

        if (!agentNetwork.getAgent(msg.sender).isActive) revert ConsumerNotRegistered();
        if (!agentNetwork.getAgent(provider).isActive) revert ProviderNotRegistered();

        uint256 fee = (price * paymentFeeRate) / 10000;
        uint256 totalAmount = price + fee;

        if (token.balanceOf(msg.sender) < totalAmount) revert InsufficientBalance();
        if (token.allowance(msg.sender, address(this)) < totalAmount) revert InsufficientAllowance();

        if (!token.transferFrom(msg.sender, address(this), totalAmount)) revert TokenTransferFailed();

        uint256 serviceId = totalServices;
        services[serviceId] = Service({
            provider: provider,
            consumer: msg.sender,
            price: price,
            escrowedAmount: totalAmount,
            timestamp: block.timestamp,
            completionTime: 0,
            status: ServiceStatus.Escrowed,
            serviceTypeCID: serviceTypeCID,
            resultCID: ""
        });

        totalServices++;

        emit ServiceCreated(serviceId, provider, msg.sender, price);

        return serviceId;
    }

    function completeServiceOrder(
        uint256 serviceId,
        string calldata resultCID
    ) external nonReentrant whenNotPaused {
        Service storage service = services[serviceId];
        if (service.timestamp == 0) revert PaymentNotFound();
        if (service.provider != msg.sender) revert NotServiceProvider();
        if (service.status != ServiceStatus.Escrowed) revert ServiceNotEscrowed();
        if (bytes(resultCID).length == 0) revert InvalidResultCID();
        if (block.timestamp > service.timestamp + 30 days) revert ServiceExpired();

        uint256 providerAmount = service.price;
        
        // 更新状态（Checks-Effects-Interactions 模式）
        service.status = ServiceStatus.Completed;
        service.completionTime = block.timestamp;
        service.resultCID = resultCID;
        totalVolume += service.price;

        // 外部调用放在最后（Interactions）
        require(
            token.transfer(service.provider, providerAmount),
            "Transfer to provider failed"
        );

        emit ServiceCompleted(serviceId, service.provider, providerAmount);
    }

    function cancelServiceOrder(uint256 serviceId) external nonReentrant {
        Service storage service = services[serviceId];
        if (service.timestamp == 0) revert PaymentNotFound();
        if (service.consumer != msg.sender) revert NotServiceConsumer();
        if (service.status != ServiceStatus.Escrowed) revert ServiceNotEscrowed();
        if (block.timestamp > service.timestamp + 24 hours) revert CancellationPeriodExpired();

        service.status = ServiceStatus.Cancelled;

        uint256 refundAmount = service.escrowedAmount;
        if (!token.transfer(service.consumer, refundAmount)) revert RefundTransferFailed();

        emit ServiceCancelled(serviceId, refundAmount);
    }

    // ============ 管理函数 ============

    function setPaymentFeeRate(uint256 _rate) external onlyOwner {
        if (_rate > 100) revert RateTooHigh();
        paymentFeeRate = _rate;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    // ============ 查询函数 ============

    function getPayment(string calldata paymentId) external view returns (Payment memory) {
        return payments[paymentId];
    }

    function getServiceOrder(uint256 serviceId) external view returns (Service memory) {
        return services[serviceId];
    }

    function getPaymentStats()
        external
        view
        returns (uint256 _totalPayments, uint256 _totalServices, uint256 _totalVolume)
    {
        return (totalPayments, totalServices, totalVolume);
    }
    
    // ============ 内部辅助函数 ============
    
    /**
     * @dev 获取实际的智能体地址（支持 AA 账户）
     * @param caller 调用者地址
     * @return 实际的智能体地址
     */
    function _getActualAgent(address caller) internal view returns (address) {
        // 首先检查调用者本身是否是注册的智能体
        if (agentNetwork.getAgent(caller).isActive) {
            return caller;
        }
        
        // 如果不是，检查是否是某个智能体的 AA 账户
        // 这需要遍历或使用反向映射（为了简化，这里返回调用者）
        // 实际实现中，可以在 AgentNetwork 中添加 aaAccountToAgent 映射
        return caller;
    }

    receive() external payable {}
}

contracts/DIAPToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20BurnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

/**
 * @title DIAPToken
 * @dev DIAP智能体网络代币合约
 * @notice 支持质押、奖励分配、通缩机制
 */
contract DIAPToken is 
    Initializable,
    ERC20Upgradeable,
    ERC20BurnableUpgradeable,
    ERC20PausableUpgradeable,
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable
{
    
    // ============ Custom Errors ============
    
    error ContractEmergencyPaused();
    error AmountMustBeGreaterThanZero();
    error InvalidTier();
    error AmountBelowTierMinimum();
    error TierChangeNotAllowed();
    error TierMismatch();
    error AmountExceedsTierLimit();
    error NoStakingFound();
    error LockPeriodNotEnded();
    error NoRewardsToClaim();
    error ActionNotScheduled();
    error TimelockNotExpired();
    error RateTooHigh();
    error MultiplierTooLow();
    error ExceedsMaxSupply();
    error EmergencyWithdrawNotEnabled();
    error TotalAllocationMismatch();
    error InsufficientBalance();
    error RateAdjustmentTooFrequent();
    
    // ============ 代币配置 ============
    
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10**18; // 10亿代币
    uint256 public constant INITIAL_SUPPLY = 100_000_000 * 10**18; // 1亿初始供应
    
    // 分配比例 (基点)
    uint256 public constant COMMUNITY_ALLOCATION = 4000; // 40% 社区
    uint256 public constant TREASURY_ALLOCATION = 2200;  // 22% 国库
    uint256 public constant TEAM_ALLOCATION = 1500;      // 15% 开发者
    uint256 public constant INVESTOR_ALLOCATION = 1500;  // 15% 投资人
    uint256 public constant STAKING_ALLOCATION = 800;    // 8% 质押奖励池
    
    // ============ 质押机制 ============
    
    struct StakingInfo {
        uint256 amount;           // 质押数量
        uint256 startTime;        // 开始时间
        uint256 lockPeriod;       // 锁定期
        uint256 lastClaimTime;    // 上次领取时间
        uint256 pendingRewards;   // 待领取奖励
    }
    
    struct StakingTier {
        uint256 minAmount;        // 最小质押数量
        uint256 multiplier;       // 奖励倍数 (基点)
        uint256 lockPeriod;       // 锁定期
    }
    
    mapping(address => StakingInfo) public stakingInfo;
    mapping(uint256 => StakingTier) public stakingTiers;
    
    uint256 public totalStaked;
    uint256 public totalRewardsDistributed;
    uint256 public stakingRewardRate; // 基础奖励率 (基点)
    uint256 public lastRewardTime;
    
    // 动态奖励率调整相关变量
    uint256 public constant MIN_REWARD_RATE = 100; // 最低1%年化
    uint256 public constant MAX_REWARD_RATE = 1000; // 最高10%年化
    uint256 public constant RATE_ADJUSTMENT_INTERVAL = 30 days; // 30天调整一次
    
    // 奖励率调整历史
    mapping(uint256 => uint256) public rewardRateHistory; // blockNumber => rate
    uint256 public lastRateAdjustment;
    
    // 质押层级
    uint256 public constant TIER_BRONZE = 0;
    uint256 public constant TIER_SILVER = 1;
    uint256 public constant TIER_GOLD = 2;
    uint256 public constant TIER_PLATINUM = 3;
    
    // ============ 通缩机制 ============
    
    uint256 public totalBurned;
    uint256 public burnRate; // 交易燃烧率 (基点)
    address public burnAddress;
    
    // 紧急控制机制
    bool public emergencyPaused = false;
    bool public emergencyWithdrawEnabled = false;
    
    // 时间锁机制
    mapping(bytes32 => uint256) public pendingActions;
    uint256 public constant TIMELOCK_DELAY = 2 days;
    
    // ============ 事件定义 ============
    
    event Staked(
        address indexed user,
        uint256 amount,
        uint256 lockPeriod,
        uint256 tier
    );
    
    event Unstaked(
        address indexed user,
        uint256 amount,
        uint256 rewards
    );
    
    event RewardsClaimed(
        address indexed user,
        uint256 amount
    );
    
    event TokensBurned(
        address indexed from,
        uint256 amount,
        string reason
    );
    
    event InitialDistributionCompleted(
        uint256 communityAmount,
        uint256 teamAmount,
        uint256 treasuryAmount,
        uint256 stakingAmount,
        uint256 liquidityAmount
    );
    
    event StakingRewardRateUpdated(uint256 newRate);
    event BurnRateUpdated(uint256 newRate);
    
    // 奖励池警告事件
    event RewardPoolLow(
        address indexed user,
        uint256 paidAmount,
        uint256 unpaidAmount
    );
    
    event RewardPoolDepleted(
        address indexed user,
        uint256 unpaidAmount
    );
    
    event RewardPoolReplenished(
        address indexed from,
        uint256 amount,
        uint256 newBalance
    );
    
    event StakingTierUpdated(
        uint256 tier,
        uint256 minAmount,
        uint256 multiplier,
        uint256 lockPeriod
    );
    
    // 紧急控制事件
    event EmergencyPaused(uint256 timestamp);
    event EmergencyUnpaused(uint256 timestamp);
    event EmergencyWithdrawEnabled(uint256 timestamp);
    event EmergencyWithdraw(address indexed user, uint256 amount);
    
    // 时间锁事件
    event ActionScheduled(bytes32 indexed actionHash, uint256 executeTime);
    event ActionExecuted(bytes32 indexed actionHash);
    
    // ============ 初始化函数 ============
    
    function initialize(string calldata tokenName, string calldata tokenSymbol) public initializer {
        __ERC20_init(tokenName, tokenSymbol);
        __ERC20Burnable_init();
        __ERC20Pausable_init();
        __Ownable_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();
        
        // 设置默认参数
        stakingRewardRate = 500; // 5% 年化
        burnRate = 25; // 0.25%
        burnAddress = address(0x000000000000000000000000000000000000dEaD);
        lastRewardTime = block.timestamp;
        lastRateAdjustment = block.timestamp;
        
        // 初始化质押层级
        _initializeStakingTiers();
        
        // 执行初始分配
        _performInitialDistribution();
    }
    
    /**
     * @dev 执行初始代币分配
     * 分配方案: 社区40%, 国库22%, 开发者15%, 投资人15%, 质押奖励池8%
     */
    function _performInitialDistribution() internal {
        // 社区分配 (40%) - 分配给部署者，后续可转移
        uint256 communityAmount = INITIAL_SUPPLY * COMMUNITY_ALLOCATION / 10000;
        _mint(msg.sender, communityAmount);
        
        // 国库分配 (22%) - 分配给部署者，后续可转移到国库地址
        uint256 treasuryAmount = INITIAL_SUPPLY * TREASURY_ALLOCATION / 10000;
        _mint(msg.sender, treasuryAmount);
        
        // 开发者分配 (15%) - 分配给部署者，后续可转移
        uint256 teamAmount = INITIAL_SUPPLY * TEAM_ALLOCATION / 10000;
        _mint(msg.sender, teamAmount);
        
        // 投资人分配 (15%) - 分配给部署者，后续可转移
        uint256 investorAmount = INITIAL_SUPPLY * INVESTOR_ALLOCATION / 10000;
        _mint(msg.sender, investorAmount);
        
        // 质押奖励池 (8%) - 分配给合约地址，用于质押奖励
        uint256 stakingAmount = INITIAL_SUPPLY * STAKING_ALLOCATION / 10000;
        _mint(address(this), stakingAmount);
        
        // 验证总分配量等于初始供应量
        uint256 totalAllocated = communityAmount + treasuryAmount + teamAmount + investorAmount + stakingAmount;
        if (totalAllocated != INITIAL_SUPPLY) revert TotalAllocationMismatch();
        
        emit InitialDistributionCompleted(
            communityAmount,
            teamAmount,
            treasuryAmount,
            stakingAmount,
            investorAmount
        );
    }
    
    function _initializeStakingTiers() internal {
        // 青铜级: 1000-9999 代币, 1x 奖励, 30天锁定期
        stakingTiers[TIER_BRONZE] = StakingTier({
            minAmount: 1000 * 10**18,
            multiplier: 10000, // 1x
            lockPeriod: 30 days
        });
        
        // 白银级: 10000-49999 代币, 1.5x 奖励, 90天锁定期
        stakingTiers[TIER_SILVER] = StakingTier({
            minAmount: 10000 * 10**18,
            multiplier: 15000, // 1.5x
            lockPeriod: 90 days
        });
        
        // 黄金级: 50000-99999 代币, 2x 奖励, 180天锁定期
        stakingTiers[TIER_GOLD] = StakingTier({
            minAmount: 50000 * 10**18,
            multiplier: 20000, // 2x
            lockPeriod: 180 days
        });
        
        // 铂金级: 100000+ 代币, 3x 奖励, 365天锁定期
        stakingTiers[TIER_PLATINUM] = StakingTier({
            minAmount: 100000 * 10**18,
            multiplier: 30000, // 3x
            lockPeriod: 365 days
        });
    }
    
    // ============ 质押功能 ============
    
    /**
     * @dev 质押代币
     * @param amount 质押数量
     * @param tier 质押层级
     */
    function stake(uint256 amount, uint256 tier) external nonReentrant whenNotPaused {
        if (emergencyPaused) revert ContractEmergencyPaused();
        if (amount == 0) revert AmountMustBeGreaterThanZero();
        if (tier > TIER_PLATINUM) revert InvalidTier();
        
        StakingTier memory tierInfo = stakingTiers[tier];
        if (amount < tierInfo.minAmount) revert AmountBelowTierMinimum();
        
        StakingInfo storage info = stakingInfo[msg.sender];
        
        // 支持追加质押
        if (info.amount > 0) {
            // 先计算并累积现有奖励
            uint256 existingRewards = _calculateRewards(msg.sender);
            info.pendingRewards += existingRewards;
            
            // 严格的层级验证
            uint256 newTotalAmount = info.amount + amount;
            uint256 currentTier = _getStakingTier(info.amount);
            uint256 newTier = _getStakingTier(newTotalAmount);
            
            // 不允许层级跳跃
            if (newTier != currentTier) revert TierChangeNotAllowed();
            if (newTier != tier) revert TierMismatch();
            
            // 检查是否超过当前层级的最大限制
            if (tier < TIER_PLATINUM) {
                if (newTotalAmount >= stakingTiers[tier + 1].minAmount) revert AmountExceedsTierLimit();
            }
            
            // 更新质押信息
            info.amount = newTotalAmount;
            info.lastClaimTime = block.timestamp;
        } else {
            // 首次质押
            info.amount = amount;
            info.startTime = block.timestamp;
            info.lockPeriod = tierInfo.lockPeriod;
            info.lastClaimTime = block.timestamp;
            info.pendingRewards = 0;
        }
        
        // 转移代币到合约
        _transfer(msg.sender, address(this), amount);
        totalStaked += amount;
        
        emit Staked(msg.sender, amount, tierInfo.lockPeriod, tier);
    }
    
    /**
     * @dev 取消质押
     */
    function unstake() external nonReentrant {
        StakingInfo storage info = stakingInfo[msg.sender];
        if (info.amount == 0) revert NoStakingFound();
        if (block.timestamp < info.startTime + info.lockPeriod) revert LockPeriodNotEnded();
        
        // 计算奖励
        uint256 rewards = _calculateRewards(msg.sender);
        
        // 清零质押信息
        totalStaked -= info.amount;
        delete stakingInfo[msg.sender];
        
        // 转移质押代币
        _transfer(address(this), msg.sender, info.amount);
        
        // 使用混合奖励系统分发奖励
        if (rewards > 0) {
            _distributeRewards(msg.sender, rewards);
        }
        
        emit Unstaked(msg.sender, info.amount, rewards);
    }
    
    /**
     * @dev 领取奖励
     */
    function claimRewards() external nonReentrant {
        StakingInfo storage info = stakingInfo[msg.sender];
        if (info.amount == 0) revert NoStakingFound();
        
        uint256 rewards = _calculateRewards(msg.sender);
        if (rewards == 0) revert NoRewardsToClaim();
        
        // 更新领取时间
        info.lastClaimTime = block.timestamp;
        info.pendingRewards = 0;
        
        // 使用混合奖励系统：优先从staking池支付，不足时铸造
        _distributeRewards(msg.sender, rewards);
        
        emit RewardsClaimed(msg.sender, rewards);
    }
    
    /**
     * @dev 计算奖励
     * @param user 用户地址
     * @return 奖励数量
     */
    function _calculateRewards(address user) internal view returns (uint256) {
        StakingInfo memory info = stakingInfo[user];
        if (info.amount == 0) return 0;
        
        // 确定质押层级
        uint256 tier = _getStakingTier(info.amount);
        StakingTier memory tierInfo = stakingTiers[tier];
        
        // 计算时间差
        uint256 timeElapsed = block.timestamp - info.lastClaimTime;
        if (timeElapsed == 0) return info.pendingRewards;
        
        // 计算基础奖励
        uint256 baseRewards = info.amount * stakingRewardRate * timeElapsed / (365 days * 10000);
        
        // 应用层级倍数
        uint256 tierRewards = baseRewards * tierInfo.multiplier / 10000;
        
        return info.pendingRewards + tierRewards;
    }
    
    /**
     * @dev 获取质押层级
     * @param amount 质押数量
     * @return 层级
     */
    function _getStakingTier(uint256 amount) internal view returns (uint256) {
        if (amount >= stakingTiers[TIER_PLATINUM].minAmount) return TIER_PLATINUM;
        if (amount >= stakingTiers[TIER_GOLD].minAmount) return TIER_GOLD;
        if (amount >= stakingTiers[TIER_SILVER].minAmount) return TIER_SILVER;
        return TIER_BRONZE;
    }
    
    /**
     * @dev 动态奖励分发系统（改进版）
     * @param recipient 接收者
     * @param amount 奖励数量
     */
    function _distributeRewards(address recipient, uint256 amount) internal {
        uint256 contractBalance = balanceOf(address(this));
        
        // 如果奖励池完全耗尽，记录待支付奖励
        if (contractBalance == 0) {
            // 记录到用户的待领取奖励中
            StakingInfo storage info = stakingInfo[recipient];
            info.pendingRewards += amount;
            
            // 发出警告事件
            emit RewardPoolDepleted(recipient, amount);
            return;
        }
        
        if (contractBalance >= amount) {
            // 余额充足，直接转账
            _transfer(address(this), recipient, amount);
            totalRewardsDistributed += amount;
        } else {
            // 余额不足但还有一些，按比例支付
            // 计算可支付的比例
            uint256 payableAmount = contractBalance;
            uint256 unpaidAmount = amount - payableAmount;
            
            // 支付可支付部分
            _transfer(address(this), recipient, payableAmount);
            totalRewardsDistributed += payableAmount;
            
            // 未支付部分记录到待领取奖励
            StakingInfo storage info = stakingInfo[recipient];
            info.pendingRewards += unpaidAmount;
            
            // 自动调整奖励率，防止进一步耗尽
            if (block.timestamp >= lastRateAdjustment + RATE_ADJUSTMENT_INTERVAL) {
                _adjustRewardRate();
            }
            
            // 发出警告事件
            emit RewardPoolLow(recipient, payableAmount, unpaidAmount);
        }
    }
    
    /**
     * @dev 动态调整奖励率
     * 当合约余额不足时，降低奖励率
     * 当合约余额充足时，适当提高奖励率
     */
    function _adjustRewardRate() internal {
        if (block.timestamp < lastRateAdjustment + RATE_ADJUSTMENT_INTERVAL) revert RateAdjustmentTooFrequent();
        
        uint256 contractBalance = balanceOf(address(this));
        uint256 totalStakedAmount = totalStaked;
        
        if (totalStakedAmount == 0) return;
        
        // 计算余额与质押量的比例
        uint256 balanceRatio = contractBalance * 10000 / totalStakedAmount;
        
        // 根据余额比例调整奖励率
        if (balanceRatio < 1000) { // 余额不足10%
            // 大幅降低奖励率
            stakingRewardRate = stakingRewardRate * 80 / 100; // 降低20%
        } else if (balanceRatio < 2000) { // 余额不足20%
            // 适度降低奖励率
            stakingRewardRate = stakingRewardRate * 90 / 100; // 降低10%
        } else if (balanceRatio > 5000) { // 余额超过50%
            // 适当提高奖励率
            stakingRewardRate = stakingRewardRate * 105 / 100; // 提高5%
        }
        
        // 确保奖励率在合理范围内
        if (stakingRewardRate < MIN_REWARD_RATE) {
            stakingRewardRate = MIN_REWARD_RATE;
        } else if (stakingRewardRate > MAX_REWARD_RATE) {
            stakingRewardRate = MAX_REWARD_RATE;
        }
        
        // 记录调整历史
        rewardRateHistory[block.number] = stakingRewardRate;
        lastRateAdjustment = block.timestamp;
        
        emit StakingRewardRateUpdated(stakingRewardRate);
    }
    
    /**
     * @dev 计算调整后的奖励
     * @param user 用户地址
     * @return 调整后的奖励数量
     */
    function _calculateAdjustedRewards(address user) internal view returns (uint256) {
        // 基于当前调整后的奖励率重新计算奖励
        StakingInfo memory info = stakingInfo[user];
        if (info.amount == 0) return 0;
        
        uint256 tier = _getStakingTier(info.amount);
        StakingTier memory tierInfo = stakingTiers[tier];
        
        uint256 timeElapsed = block.timestamp - info.lastClaimTime;
        if (timeElapsed == 0) return info.pendingRewards;
        
        uint256 baseRewards = info.amount * stakingRewardRate * timeElapsed / (365 days * 10000);
        uint256 tierRewards = baseRewards * tierInfo.multiplier / 10000;
        
        return info.pendingRewards + tierRewards;
    }
    
    // ============ 通缩机制 ============
    
    /**
     * @dev 燃烧代币
     * @param amount 燃烧数量
     * @param reason 燃烧原因
     */
    function burnTokens(uint256 amount, string calldata reason) external {
        if (amount == 0) revert AmountMustBeGreaterThanZero();
        if (balanceOf(msg.sender) < amount) revert InsufficientBalance();
        
        _burn(msg.sender, amount);
        totalBurned += amount;
        
        emit TokensBurned(msg.sender, amount, reason);
    }
    
    /**
     * @dev 自动燃烧 (在转账时)
     * @param from 发送方
     * @param to 接收方
     * @param amount 数量
     */
    function _transfer(address from, address to, uint256 amount) internal override {
        if (burnRate > 0 && from != address(this) && to != address(this)) {
            uint256 burnAmount = amount * burnRate / 10000;
            if (burnAmount > 0) {
                // 统一使用 _burn 函数，确保减少 totalSupply
                _burn(from, burnAmount);
                totalBurned += burnAmount;
                amount -= burnAmount;
                
                emit TokensBurned(from, burnAmount, "Auto-burn on transfer");
            }
        }
        
        super._transfer(from, to, amount);
    }
    
    // ============ 管理函数 ============
    
    /**
     * @dev 设置质押奖励率 (需要时间锁)
     * @param _rate 奖励率 (基点/年，例如500 = 5% APY)
     */
    function setStakingRewardRate(uint256 _rate) external onlyOwner {
        bytes32 actionHash = keccak256(abi.encodePacked("setStakingRewardRate", _rate));
        if (pendingActions[actionHash] == 0) revert ActionNotScheduled();
        if (pendingActions[actionHash] > block.timestamp) revert TimelockNotExpired();
        
        if (_rate > MAX_REWARD_RATE) revert RateTooHigh();
        stakingRewardRate = _rate;
        delete pendingActions[actionHash];
        
        emit StakingRewardRateUpdated(_rate);
        emit ActionExecuted(actionHash);
    }
    
    /**
     * @dev 安排奖励率调整
     * @param _rate 新的奖励率
     */
    function scheduleRewardRateChange(uint256 _rate) external onlyOwner {
        if (_rate > MAX_REWARD_RATE) revert RateTooHigh();
        bytes32 actionHash = keccak256(abi.encodePacked("setStakingRewardRate", _rate));
        pendingActions[actionHash] = block.timestamp + TIMELOCK_DELAY;
        emit ActionScheduled(actionHash, block.timestamp + TIMELOCK_DELAY);
    }
    
    /**
     * @dev 设置燃烧率
     * @param _rate 燃烧率 (基点，例如25 = 0.25%)
     */
    function setBurnRate(uint256 _rate) external onlyOwner {
        if (_rate > 100) revert RateTooHigh(); // 最大1%
        burnRate = _rate;
        emit BurnRateUpdated(_rate);
    }
    
    /**
     * @dev 补充奖励池（仅限 owner）
     * @param amount 补充数量
     * @notice 从 owner 账户转移代币到合约作为奖励池
     */
    function replenishRewardPool(uint256 amount) external onlyOwner {
        if (amount == 0) revert AmountMustBeGreaterThanZero();
        
        // 从 owner 转移到合约
        _transfer(msg.sender, address(this), amount);
        
        emit RewardPoolReplenished(msg.sender, amount, balanceOf(address(this)));
    }
    
    /**
     * @dev 获取奖励池状态
     * @return balance 当前余额
     * @return ratio 余额/质押量比例（百分比）
     * @return isHealthy 是否健康（>10%）
     */
    function getRewardPoolStatus() external view returns (
        uint256 balance,
        uint256 ratio,
        bool isHealthy
    ) {
        balance = balanceOf(address(this));
        
        if (totalStaked > 0) {
            ratio = balance * 100 / totalStaked;
            isHealthy = ratio >= 10; // 至少10%
        } else {
            ratio = 0;
            isHealthy = true; // 没有质押时认为健康
        }
        
        return (balance, ratio, isHealthy);
    }
    
    /**
     * @dev 更新质押层级
     * @param tier 层级
     * @param minAmount 最小数量
     * @param multiplier 倍数
     * @param lockPeriod 锁定期
     */
    function updateStakingTier(
        uint256 tier,
        uint256 minAmount,
        uint256 multiplier,
        uint256 lockPeriod
    ) external onlyOwner {
        if (tier > TIER_PLATINUM) revert InvalidTier();
        if (multiplier < 10000) revert MultiplierTooLow(); // 最小1x
        
        stakingTiers[tier] = StakingTier({
            minAmount: minAmount,
            multiplier: multiplier,
            lockPeriod: lockPeriod
        });
        
        emit StakingTierUpdated(tier, minAmount, multiplier, lockPeriod);
    }
    
    /**
     * @dev 铸造代币 (仅限合约调用)
     * @param to 接收方
     * @param amount 数量
     */
    function mint(address to, uint256 amount) external onlyOwner {
        if (totalSupply() + amount > MAX_SUPPLY) revert ExceedsMaxSupply();
        _mint(to, amount);
    }
    
    function pause() external onlyOwner {
        _pause();
    }
    
    function unpause() external onlyOwner {
        _unpause();
    }
    
    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}
    
    // ============ 紧急控制函数 ============
    
    /**
     * @dev 紧急暂停合约
     */
    function emergencyPause() external onlyOwner {
        emergencyPaused = true;
        emit EmergencyPaused(block.timestamp);
    }
    
    /**
     * @dev 取消紧急暂停
     */
    function emergencyUnpause() external onlyOwner {
        emergencyPaused = false;
        emit EmergencyUnpaused(block.timestamp);
    }
    
    /**
     * @dev 启用紧急提取
     */
    function enableEmergencyWithdraw() external onlyOwner {
        emergencyWithdrawEnabled = true;
        emit EmergencyWithdrawEnabled(block.timestamp);
    }
    
    /**
     * @dev 紧急提取质押代币
     */
    function emergencyWithdraw() external {
        if (!emergencyWithdrawEnabled) revert EmergencyWithdrawNotEnabled();
        StakingInfo storage info = stakingInfo[msg.sender];
        if (info.amount == 0) revert NoStakingFound();
        
        uint256 amount = info.amount;
        delete stakingInfo[msg.sender];
        totalStaked -= amount;
        
        _transfer(address(this), msg.sender, amount);
        emit EmergencyWithdraw(msg.sender, amount);
    }
    
    // ============ 查询函数 ============
    
    /**
     * @dev 获取用户质押信息
     * @param user 用户地址
     * @return amount 质押数量
     * @return startTime 开始时间
     * @return lockPeriod 锁定期
     * @return lastClaimTime 上次领取时间
     * @return pendingRewards 待领取奖励
     * @return tier 质押层级
     */
    function getStakingInfo(address user) external view returns (
        uint256 amount,
        uint256 startTime,
        uint256 lockPeriod,
        uint256 lastClaimTime,
        uint256 pendingRewards,
        uint256 tier
    ) {
        StakingInfo memory info = stakingInfo[user];
        return (
            info.amount,
            info.startTime,
            info.lockPeriod,
            info.lastClaimTime,
            _calculateRewards(user),
            _getStakingTier(info.amount)
        );
    }
    
    /**
     * @dev 获取质押层级信息
     * @param tier 层级
     * @return minAmount 最小质押数量
     * @return multiplier 奖励倍数
     * @return lockPeriod 锁定期
     */
    function getStakingTier(uint256 tier) external view returns (
        uint256 minAmount,
        uint256 multiplier,
        uint256 lockPeriod
    ) {
        StakingTier memory tierInfo = stakingTiers[tier];
        return (tierInfo.minAmount, tierInfo.multiplier, tierInfo.lockPeriod);
    }
    
    /**
     * @dev 获取代币统计信息
     * @return totalSupply_ 总供应量
     * @return totalStaked_ 总质押量
     * @return totalBurned_ 总燃烧量
     * @return totalRewards_ 总奖励
     */
    function getTokenStats() external view returns (
        uint256 totalSupply_,
        uint256 totalStaked_,
        uint256 totalBurned_,
        uint256 totalRewards_
    ) {
        return (totalSupply(), totalStaked, totalBurned, totalRewardsDistributed);
    }
    
    // ============ 重写函数 ============
    
    function _beforeTokenTransfer(
        address from,
        address to,
        uint256 amount
    ) internal override(ERC20Upgradeable, ERC20PausableUpgradeable) {
        super._beforeTokenTransfer(from, to, amount);
    }
}

contracts/DIAPVerification.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "./DIAPAgentNetwork.sol";
import "./IZKPVerifier.sol";

/**
 * @title DIAPVerification
 * @dev DIAP智能体网络验证合约
 * @notice 集成Noir ZKP验证，支持身份验证和防恶意行为
 */
contract DIAPVerification is 
    Initializable,
    UUPSUpgradeable,
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable
{
    
    // ============ Custom Errors ============
    
    error InvalidAgentNetworkAddress();
    error AgentIsBlacklisted();
    error InvalidDIDDocumentLength();
    error InvalidPublicKeyLength();
    error InvalidCommitment();
    error InvalidNullifier();
    error NullifierAlreadyUsed();
    error TooManyFailedAttempts();
    error SessionNotFound();
    error SessionNotPending();
    error SessionExpired();
    error InvalidReputationScore();
    error ArraysLengthMismatch();
    error TooManyAgents();
    error AgentAlreadyBlacklisted();
    error AgentNotBlacklisted();
    error NullifierNotUsed();
    error TimeoutMustBeGreaterThanZero();
    error AttemptsMustBeGreaterThanZero();
    error OnlyOwnerCanVerify();
    error OnlyZKPVerifierCanVerify();
    error UnauthorizedVerifier();
    
    // ============ 结构体定义 ============
    
    struct VerificationSession {
        address agent;
        string didDocument;  // DID文档标识符 (支持IPNS名称和IPFS CID)
        string publicKey;
        bytes32 commitment;  // 添加commitment存储
        bytes32 nullifier;   // 添加nullifier存储
        uint256 timestamp;
        VerificationStatus status;
        uint256[8] proof;
        bool isValid;
    }
    
    struct IdentityProof {
        string didDocument;  // DID文档标识符 (支持IPNS名称和IPFS CID)
        string publicKey;
        bytes32 commitment;
        bytes32 nullifier;
        uint256[8] proof;
        uint256 timestamp;
        bool isVerified;
    }
    
    struct ReputationProof {
        address agent;
        uint256 reputation;
        uint256 timestamp;
        uint256[8] proof;
        bool isValid;
    }
    
    enum VerificationStatus {
        PENDING,
        VERIFIED,
        FAILED,
        EXPIRED
    }
    
    // ============ 状态变量 ============
    
    DIAPAgentNetwork public agentNetwork;
    
    mapping(bytes32 => VerificationSession) public verificationSessions;
    mapping(address => IdentityProof) public identityProofs;
    mapping(address => ReputationProof) public reputationProofs;
    
    uint256 public totalVerifications;
    uint256 public totalSuccessfulVerifications;
    uint256 public totalFailedVerifications;
    
    // 验证参数
    uint256 public verificationTimeout;     // 验证超时时间
    uint256 public maxVerificationAttempts; // 最大验证尝试次数
    uint256 public reputationThreshold;     // 声誉阈值
    
    // ZKP验证器地址
    address public zkpVerifier;
    
    // 恶意行为检测
    mapping(address => uint256) public failedAttempts;
    mapping(address => uint256) public lastFailedAttempt;
    mapping(address => bool) public blacklistedAgents;
    
    // nullifier管理
    mapping(bytes32 => bool) public usedNullifiers;
    
    // 字符串长度限制
    uint256 public constant MAX_STRING_LENGTH = 1000;
    
    // 验证模式枚举
    enum VerificationMode {
        OWNER_MANUAL,    // 仅owner手动验证
        ZKP_AUTOMATED,   // ZKP自动验证
        HYBRID          // 混合模式
    }
    
    VerificationMode public verificationMode = VerificationMode.HYBRID;
    
    // ============ 事件定义 ============
    
    event VerificationInitiated(
        bytes32 indexed sessionId,
        address indexed agent,
        string didDocument
    );
    
    event VerificationCompleted(
        bytes32 indexed sessionId,
        address indexed agent,
        bool isValid
    );
    
    event IdentityVerified(
        address indexed agent,
        string didDocument,
        uint256 timestamp
    );
    
    event ReputationVerified(
        address indexed agent,
        uint256 reputation,
        uint256 timestamp
    );
    
    event AgentBlacklisted(
        address indexed agent,
        string reason,
        uint256 timestamp
    );
    
    event AgentWhitelisted(
        address indexed agent,
        uint256 timestamp
    );
    
    event ZKPVerifierUpdated(
        address oldVerifier,
        address newVerifier
    );
    
    event VerificationTimeoutUpdated(uint256 oldTimeout, uint256 newTimeout);
    event MaxVerificationAttemptsUpdated(uint256 oldAttempts, uint256 newAttempts);
    event ReputationThresholdUpdated(uint256 oldThreshold, uint256 newThreshold);
    event NullifierUsed(bytes32 indexed nullifier, address indexed agent);
    event VerificationModeUpdated(VerificationMode newMode);
    
    // ============ 修饰符 ============
    
    /**
     * @dev 仅允许授权验证器调用
     */
    modifier onlyAuthorizedVerifier() {
        if (verificationMode == VerificationMode.OWNER_MANUAL) {
            if (msg.sender != owner()) revert OnlyOwnerCanVerify();
        } else if (verificationMode == VerificationMode.ZKP_AUTOMATED) {
            if (msg.sender != zkpVerifier) revert OnlyZKPVerifierCanVerify();
        } else { // HYBRID
            if (msg.sender != owner() && msg.sender != zkpVerifier) revert UnauthorizedVerifier();
        }
        _;
    }
    
    // ============ 初始化函数 ============
    
    function initialize(address _agentNetwork) public initializer {
        if (_agentNetwork == address(0)) revert InvalidAgentNetworkAddress();
        
        __Ownable_init();
        __UUPSUpgradeable_init();
        __ReentrancyGuard_init();
        
        agentNetwork = DIAPAgentNetwork(payable(_agentNetwork));
        
        // 设置默认参数
        verificationTimeout = 1 hours;
        maxVerificationAttempts = 3;
        reputationThreshold = 1000;
    }
    
    // ============ 身份验证功能 ============
    
    /**
     * @dev 发起身份验证
     * @param didDocument DID文档标识符 (支持IPNS名称和IPFS CID)
     * @param publicKey 公钥
     * @param commitment 承诺
     * @param nullifier 空值
     * @param proof ZKP证明
     * @return sessionId 会话ID
     */
    function initiateIdentityVerification(
        string calldata didDocument,
        string calldata publicKey,
        bytes32 commitment,
        bytes32 nullifier,
        uint256[8] calldata proof
    ) external nonReentrant returns (bytes32) {
        if (blacklistedAgents[msg.sender]) revert AgentIsBlacklisted();
        if (bytes(didDocument).length == 0 || bytes(didDocument).length > MAX_STRING_LENGTH) revert InvalidDIDDocumentLength();
        if (bytes(publicKey).length == 0 || bytes(publicKey).length > MAX_STRING_LENGTH) revert InvalidPublicKeyLength();
        if (commitment == bytes32(0)) revert InvalidCommitment();
        if (nullifier == bytes32(0)) revert InvalidNullifier();
        if (usedNullifiers[nullifier]) revert NullifierAlreadyUsed(); // 防止重放攻击
        
        // 立即标记nullifier为已使用，防止重放攻击
        usedNullifiers[nullifier] = true;
        
        // 检查验证尝试次数
        if (failedAttempts[msg.sender] >= maxVerificationAttempts) revert TooManyFailedAttempts();
        
        // 生成防碰撞的sessionId
        bytes32 sessionId = keccak256(abi.encodePacked(
            msg.sender,
            didDocument,
            publicKey,
            commitment,
            nullifier,
            block.timestamp,
            block.number
        ));
        
        // 正确保存所有会话数据
        verificationSessions[sessionId] = VerificationSession({
            agent: msg.sender,
            didDocument: didDocument,
            publicKey: publicKey,
            commitment: commitment,  // 保存commitment
            nullifier: nullifier,    // 保存nullifier
            timestamp: block.timestamp,
            status: VerificationStatus.PENDING,
            proof: proof,
            isValid: false
        });
        
        totalVerifications++;
        
        emit VerificationInitiated(sessionId, msg.sender, didDocument);
        
        return sessionId;
    }
    
    /**
     * @dev 验证身份
     * @param sessionId 会话ID
     * @return 是否验证成功
     */
    function verifyIdentity(bytes32 sessionId) external onlyAuthorizedVerifier returns (bool) {
        VerificationSession storage session = verificationSessions[sessionId];
        if (session.timestamp == 0) revert SessionNotFound();
        if (session.status != VerificationStatus.PENDING) revert SessionNotPending();
        if (block.timestamp > session.timestamp + verificationTimeout) revert SessionExpired();
        
        // 验证ZKP证明
        uint256[8] memory proofCopy = session.proof;
        bool isValid = _verifyZKProof(proofCopy, session.didDocument, session.publicKey);
        
        if (isValid) {
            session.status = VerificationStatus.VERIFIED;
            session.isValid = true;
            totalSuccessfulVerifications++;
            
            // nullifier已经在initiateIdentityVerification中被标记为已使用，无需重复标记
            
            // 保存身份证明，使用会话中的commitment和nullifier
            identityProofs[session.agent] = IdentityProof({
                didDocument: session.didDocument,
                publicKey: session.publicKey,
                commitment: session.commitment,  // 使用会话中的commitment
                nullifier: session.nullifier,    // 使用会话中的nullifier
                proof: session.proof,
                timestamp: block.timestamp,
                isVerified: true
            });
            
            // 重置失败尝试次数
            failedAttempts[session.agent] = 0;
            
            emit VerificationCompleted(sessionId, session.agent, true);
            emit IdentityVerified(session.agent, session.didDocument, block.timestamp);
            emit NullifierUsed(session.nullifier, session.agent);
            
            return true;
        } else {
            session.status = VerificationStatus.FAILED;
            session.isValid = false;
            totalFailedVerifications++;
            
            // 增加失败尝试次数
            failedAttempts[session.agent]++;
            lastFailedAttempt[session.agent] = block.timestamp;
            
            // 检查是否需要加入黑名单
            if (failedAttempts[session.agent] >= maxVerificationAttempts) {
                blacklistedAgents[session.agent] = true;
                emit AgentBlacklisted(session.agent, "Too many failed verification attempts", block.timestamp);
            }
            
            emit VerificationCompleted(sessionId, session.agent, false);
            
            return false;
        }
    }
    
    // ============ 声誉验证功能 ============
    
    /**
     * @dev 验证声誉
     * @param agent 智能体地址
     * @param reputation 声誉分数
     * @param proof ZKP证明
     * @return 是否验证成功
     */
    function verifyReputation(
        address agent,
        uint256 reputation,
        uint256[8] calldata proof
    ) external onlyAuthorizedVerifier nonReentrant returns (bool) {
        if (blacklistedAgents[agent]) revert AgentIsBlacklisted();
        if (reputation > 10000) revert InvalidReputationScore();
        
        // 调用外部ZKP验证器进行实际验证
        bool isValid = _callExternalReputationVerifier(proof, agent, reputation);
        
        if (isValid) {
            reputationProofs[agent] = ReputationProof({
                agent: agent,
                reputation: reputation,
                timestamp: block.timestamp,
                proof: proof,
                isValid: true
            });
            
            emit ReputationVerified(agent, reputation, block.timestamp);
            
            return true;
        }
        
        return false;
    }
    
    // ============ 批量验证功能 ============
    
    /**
     * @dev 批量验证智能体
     * @param agents 智能体地址数组
     * @param proofs ZKP证明数组
     * @return 验证结果数组
     */
    function batchVerifyAgents(
        address[] calldata agents,
        uint256[8][] calldata proofs
    ) external view onlyOwner returns (bool[] memory) {
        if (agents.length != proofs.length) revert ArraysLengthMismatch();
        if (agents.length > 10) revert TooManyAgents(); // 限制批量大小
        
        bool[] memory results = new bool[](agents.length);
        
        for (uint256 i = 0; i < agents.length;) {
            if (blacklistedAgents[agents[i]]) {
                results[i] = false;
                continue;
            }
            
            // 获取智能体信息
            try agentNetwork.getAgent(agents[i]) returns (DIAPAgentNetwork.Agent memory agent) {
                if (agent.isActive) {
                    uint256[8] memory proofCopy = proofs[i];
                    results[i] = _verifyZKProof(proofCopy, agent.didDocument, agent.publicKey);
                } else {
                    results[i] = false;
                }
            } catch {
                results[i] = false;
            }
            unchecked {
                ++i;  // Gas 优化
            }
        }
        
        return results;
    }
    
    // ============ 恶意行为检测 ============
    
    /**
     * @dev 检测恶意行为
     * @param agent 智能体地址
     * @param behaviorType 行为类型
     */
    function detectMaliciousBehavior(
        address agent,
        string calldata behaviorType,
        string calldata /* evidence */
    ) external onlyOwner {
        if (blacklistedAgents[agent]) revert AgentAlreadyBlacklisted();
        
        // 根据行为类型采取不同措施
        if (keccak256(bytes(behaviorType)) == keccak256("SPAM")) {
            // 垃圾信息行为
            _handleSpamBehavior(agent);
        } else if (keccak256(bytes(behaviorType)) == keccak256("FRAUD")) {
            // 欺诈行为
            _handleFraudBehavior(agent);
        } else if (keccak256(bytes(behaviorType)) == keccak256("ATTACK")) {
            // 攻击行为
            _handleAttackBehavior(agent);
        }
        
        emit AgentBlacklisted(agent, behaviorType, block.timestamp);
    }
    
    /**
     * @dev 移除黑名单
     * @param agent 智能体地址
     */
    function removeFromBlacklist(address agent) external onlyOwner {
        if (!blacklistedAgents[agent]) revert AgentNotBlacklisted();
        
        blacklistedAgents[agent] = false;
        failedAttempts[agent] = 0;
        
        emit AgentWhitelisted(agent, block.timestamp);
    }
    
    /**
     * @dev 重置nullifier（申诉成功后）
     * @param nullifier 要重置的nullifier
     */
    function resetNullifier(bytes32 nullifier) external onlyOwner {
        if (!usedNullifiers[nullifier]) revert NullifierNotUsed();
        usedNullifiers[nullifier] = false;
    }
    
    // ============ 内部函数 ============
    
    /**
     * @dev 验证ZKP证明
     * @param proof ZKP证明
     * @param didDocument DID文档
     * @param publicKey 公钥
     * @return 是否有效
     */
    function _verifyZKProof(
        uint256[8] memory proof,
        string memory didDocument,
        string memory publicKey
    ) internal view returns (bool) {
        if (zkpVerifier == address(0)) {
            // 默认验证逻辑 (简化实现)
            return proof.length == 8 && proof[0] != 0 && bytes(didDocument).length > 0;
        }
        
        // 使用ABI-safe调用外部ZKP验证器
        try IZKPVerifier(zkpVerifier).verifyProof(proof, didDocument, publicKey) returns (bool result) {
            return result;
        } catch {
            // 验证器调用失败时返回false
            return false;
        }
    }
    
    /**
     * @dev 调用外部声誉验证器
     * @param proof ZKP证明
     * @param agent 智能体地址
     * @param reputation 声誉分数
     * @return 是否有效
     */
    function _callExternalReputationVerifier(
        uint256[8] calldata proof,
        address agent,
        uint256 reputation
    ) internal view returns (bool) {
        if (zkpVerifier == address(0)) {
            return false; // 没有验证器时拒绝
        }
        
        try IZKPVerifier(zkpVerifier).verifyReputationProof(proof, agent, reputation) returns (bool result) {
            return result;
        } catch {
            // 验证器调用失败时返回false
            return false;
        }
    }
    
    /**
     * @dev 验证声誉证明
     * @param reputation 声誉分数
     * @return 是否有效
     */
    function _verifyReputationProof(
        uint256[8] calldata /* proof */,
        address /* agent */,
        uint256 reputation
    ) internal pure returns (bool) {
        // 这里应该集成实际的声誉ZKP验证逻辑
        // 简化实现
        return reputation > 0;
    }
    
    function _handleSpamBehavior(address agent) internal {
        // 处理垃圾信息行为
        blacklistedAgents[agent] = true;
    }
    
    function _handleFraudBehavior(address agent) internal {
        // 处理欺诈行为
        blacklistedAgents[agent] = true;
    }
    
    function _handleAttackBehavior(address agent) internal {
        // 处理攻击行为
        blacklistedAgents[agent] = true;
    }
    
    // ============ 管理函数 ============
    
    function setZKPVerifier(address _verifier) external onlyOwner {
        address oldVerifier = zkpVerifier;
        zkpVerifier = _verifier;
        emit ZKPVerifierUpdated(oldVerifier, _verifier);
    }
    
    /**
     * @dev 设置验证模式
     * @param _mode 验证模式
     */
    function setVerificationMode(VerificationMode _mode) external onlyOwner {
        verificationMode = _mode;
        emit VerificationModeUpdated(_mode);
    }
    
    function setVerificationTimeout(uint256 _timeout) external onlyOwner {
        if (_timeout == 0) revert TimeoutMustBeGreaterThanZero();
        uint256 oldTimeout = verificationTimeout;
        verificationTimeout = _timeout;
        emit VerificationTimeoutUpdated(oldTimeout, _timeout);
    }
    
    function setMaxVerificationAttempts(uint256 _attempts) external onlyOwner {
        if (_attempts == 0) revert AttemptsMustBeGreaterThanZero();
        uint256 oldAttempts = maxVerificationAttempts;
        maxVerificationAttempts = _attempts;
        emit MaxVerificationAttemptsUpdated(oldAttempts, _attempts);
    }
    
    function setReputationThreshold(uint256 _threshold) external onlyOwner {
        uint256 oldThreshold = reputationThreshold;
        reputationThreshold = _threshold;
        emit ReputationThresholdUpdated(oldThreshold, _threshold);
    }
    
    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}
    
    // ============ 查询函数 ============
    
    function getVerificationSession(bytes32 sessionId) external view returns (VerificationSession memory) {
        return verificationSessions[sessionId];
    }
    
    function getIdentityProof(address agent) external view returns (IdentityProof memory) {
        return identityProofs[agent];
    }
    
    function getReputationProof(address agent) external view returns (ReputationProof memory) {
        return reputationProofs[agent];
    }
    
    function isAgentBlacklisted(address agent) external view returns (bool) {
        return blacklistedAgents[agent];
    }
    
    function getFailedAttempts(address agent) external view returns (uint256) {
        return failedAttempts[agent];
    }
    
    function getVerificationStats() external view returns (
        uint256 _totalVerifications,
        uint256 _totalSuccessfulVerifications,
        uint256 _totalFailedVerifications
    ) {
        return (totalVerifications, totalSuccessfulVerifications, totalFailedVerifications);
    }
    
    function isIdentityVerified(address agent) external view returns (bool) {
        return identityProofs[agent].isVerified;
    }
    
    function isReputationVerified(address agent) external view returns (bool) {
        return reputationProofs[agent].isValid;
    }
    
    /**
     * @dev 检查nullifier是否已被使用
     * @param nullifier nullifier值
     * @return 是否已被使用
     */
    function isNullifierUsed(bytes32 nullifier) external view returns (bool) {
        return usedNullifiers[nullifier];
    }
    
    /**
     * @dev 获取验证器状态
     * @return verifier 验证器地址
     * @return isAvailable 是否可用
     */
    function getVerifierStatus() external view returns (address verifier, bool isAvailable) {
        verifier = zkpVerifier;
        if (verifier == address(0)) {
            isAvailable = false;
        } else {
            try IZKPVerifier(verifier).isAvailable() returns (bool available) {
                isAvailable = available;
            } catch {
                isAvailable = false;
            }
        }
    }
}

contracts/IZKPVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/**
 * @title IZKPVerifier
 * @dev ZKP验证器接口合约
 * @notice 定义零知识证明验证的标准接口
 */
interface IZKPVerifier {
    /**
     * @dev 验证身份证明
     * @param proof ZKP证明数组
     * @param didDocument DID文档
     * @param publicKey 公钥
     * @return 验证是否成功
     */
    function verifyProof(
        uint256[8] calldata proof,
        string calldata didDocument,
        string calldata publicKey
    ) external view returns (bool);
    
    /**
     * @dev 验证声誉证明
     * @param proof ZKP证明数组
     * @param agent 智能体地址
     * @param reputation 声誉分数
     * @return 验证是否成功
     */
    function verifyReputationProof(
        uint256[8] calldata proof,
        address agent,
        uint256 reputation
    ) external view returns (bool);
    
    /**
     * @dev 验证批量证明
     * @param proofs 证明数组
     * @param agents 智能体地址数组
     * @param reputations 声誉分数数组
     * @return 验证结果数组
     */
    function verifyBatchProofs(
        uint256[8][] calldata proofs,
        address[] calldata agents,
        uint256[] calldata reputations
    ) external view returns (bool[] memory);
    
    /**
     * @dev 获取验证器版本信息
     * @return 版本字符串
     */
    function getVersion() external view returns (string memory);
    
    /**
     * @dev 检查验证器是否可用
     * @return 是否可用
     */
    function isAvailable() external view returns (bool);
}

